output.arguments:
{"command":"cd /workspace/internal/regex && cat > syntax.go <<'EOF'
package regex

import (
	"fmt"
	"strconv"
	"strings"
	"unicode"
)

// Flags
const (
	FlagIgnoreCase = 1 << iota
	FlagMultiline
	FlagSingleline
	FlagExplicitCapture
	FlagIgnoreSpace
)

type nodeKind int

const (
	nEmpty nodeKind = iota
	nChar
	nSet
	nAny
	nBol
	nEol
	nBeginText
	nEndTextZ
	nEndText
	nStartPos
	nWordB
	nNonWordB
	nConcat
	nAlt
	nRepeat
	nGroup
	nNonCap
	nLookahead
	nNegLookahead
	nLookbehind
	nNegLookbehind
	nAtomic
	nBackref
	nCond
	nFail
)

type node struct {
	kind     nodeKind
	ch       rune
	fold     bool // ignore case
	set      *charSet
	dotAll   bool
	multi    bool
	subs     []*node
	min, max int // repeat; max -1 = inf
	lazy     bool
	group    int
	condGrp  int // for conditional: group number or -1 for expression
	condExpr *node
}

type parser struct {
	src       []rune
	pos       int
	flags     int
	capCount  int
	names     map[string]int
	nameOrder []string
	numCaps   int
	pattern   string
}

type Error struct {
	Msg     string
	Pattern string
}

func (e *Error) Error() string {
	return fmt.Sprintf("error parsing regexp: %s in `%s`", e.Msg, e.Pattern)
}

func (p *parser) errf(format string, args ...interface{}) {
	panic(&Error{Msg: fmt.Sprintf(format, args...), Pattern: p.pattern})
}

func (p *parser) more() bool { return p.pos < len(p.src) }
func (p *parser) peek() rune {
	if p.pos < len(p.src) {
		return p.src[p.pos]
	}
	return 0
}
func (p *parser) peekAt(i int) rune {
	if p.pos+i < len(p.src) {
		return p.src[p.pos+i]
	}
	return 0
}

// prescan counts unnamed capture groups and collects names to emulate .NET numbering.
func (p *parser) prescan() {
	src := p.src
	flags := p.flags
	unnamed := 0
	var names []string
	inClass := false
	type fstack struct{ flags int }
	var stack []int
	for i := 0; i < len(src); i++ {
		c := src[i]
		if c == '\\' {
			i++
			continue
		}
		if inClass {
			if c == ']' {
				inClass = false
			}
			continue
		}
		if flags&FlagIgnoreSpace != 0 && c == '#' {
			for i < len(src) && src[i] != '\n' {
				i++
			}
			continue
		}
		switch c {
		case '[':
			inClass = true
			// handle []...] and [^]...]
			if i+1 < len(src) && src[i+1] == '^' {
				i++
			}
			if i+1 < len(src) && src[i+1] == ']' {
				i++
			}
		case '(':
			stack = append(stack, flags)
			if i+1 < len(src) && src[i+1] == '?' {
				// named?
				if i+2 < len(src) && (src[i+2] == '<' || src[i+2] == '\'') {
					if i+3 < len(src) && (src[i+3] == '=' || src[i+3] == '!') {
						continue
					}
					end := byte('>')
					if src[i+2] == '\'' {
						end = '\''
					}
					j := i + 3
					for j < len(src) && src[j] != rune(end) {
						j++
					}
					name := string(src[i+3 : j])
					if k := strings.IndexByte(name, '-'); k >= 0 {
						name = name[:k]
					}
					if name != "" {
						names = append(names, name)
					}
					continue
				}
				if i+2 < len(src) && src[i+2] == '#' {
					// comment
					for i < len(src) && src[i] != ')' {
						i++
					}
					stack = stack[:len(stack)-1]
					continue
				}
				// inline options
				j := i + 2
				on := true
				nf := flags
				for j < len(src) {
					ch := src[j]
					if ch == '-' {
						on = false
					} else if f := optFlag(ch); f != 0 {
						if on {
							nf |= f
						} else {
							nf &^= f
						}
					} else {
						break
					}
					j++
				}
				if j < len(src) && src[j] == ')' {
					// applies to the rest of the enclosing group
					stack = stack[:len(stack)-1]
					flags = nf
					i = j
				} else if j < len(src) && src[j] == ':' {
					stack[len(stack)-1] = flags
					flags = nf
					i = j
				}
				continue
			}
			if flags&FlagExplicitCapture == 0 {
				unnamed++
			}
		case ')':
			if len(stack) > 0 {
				flags = stack[len(stack)-1]
				stack = stack[:len(stack)-1]
			}
		}
	}
	p.capCount = unnamed
	p.names = map[string]int{}
	next := unnamed + 1
	for _, n := range names {
		if _, ok := p.names[n]; ok {
			continue
		}
		if num, err := strconv.Atoi(n); err == nil {
			p.names[n] = num
			continue
		}
		p.names[n] = next
		next++
	}
	p.numCaps = next - 1
	for _, v := range p.names {
		if v > p.numCaps {
			p.numCaps = v
		}
	}
}

func optFlag(c rune) int {
	switch c {
	case 'i':
		return FlagIgnoreCase
	case 'm':
		return FlagMultiline
	case 's':
		return FlagSingleline
	case 'n':
		return FlagExplicitCapture
	case 'x':
		return FlagIgnoreSpace
	}
	return 0
}

func parse(pattern string, flags int) (n *node, ncap int, names map[string]int, err error) {
	p := &parser{src: []rune(pattern), flags: flags, pattern: pattern}
	defer func() {
		if r := recover(); r != nil {
			if e, ok := r.(*Error); ok {
				err = e
				return
			}
			panic(r)
		}
	}()
	p.prescan()
	p.flags = flags
	p.capCount = 0
	n = p.parseAlt()
	if p.more() {
		if p.peek() == ')' {
			p.errf("too many )'s")
		}
		p.errf("unexpected character")
	}
	return n, p.numCaps, p.names, nil
}

func (p *parser) skipSpace() {
	if p.flags&FlagIgnoreSpace == 0 {
		return
	}
	for p.more() {
		c := p.peek()
		if c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f' || c == '\v' {
			p.pos++
			continue
		}
		if c == '#' {
			for p.more() && p.peek() != '\n' {
				p.pos++
			}
			continue
		}
		break
	}
}

func (p *parser) parseAlt() *node {
	saved := p.flags
	var alts []*node
	for {
		alts = append(alts, p.parseConcat())
		if p.more() && p.peek() == '|' {
			p.pos++
			continue
		}
		break
	}
	p.flags = saved
	if len(alts) == 1 {
		return alts[0]
	}
	return &node{kind: nAlt, subs: alts}
}

func (p *parser) parseConcat() *node {
	var items []*node
	for {
		p.skipSpace()
		if !p.more() {
			break
		}
		c := p.peek()
		if c == '|' || c == ')' {
			break
		}
		atom := p.parseAtom()
		if atom == nil {
			continue
		}
		atom = p.parseQuant(atom)
		items = append(items, atom)
	}
	if len(items) == 0 {
		return &node{kind: nEmpty}
	}
	if len(items) == 1 {
		return items[0]
	}
	return &node{kind: nConcat, subs: items}
}

func (p *parser) parseQuant(atom *node) *node {
	for {
		p.skipSpace()
		if !p.more() {
			return atom
		}
		c := p.peek()
		min, max := -1, -1
		switch c {
		case '*':
			min, max = 0, -1
			p.pos++
		case '+':
			min, max = 1, -1
			p.pos++
		case '?':
			min, max = 0, 1
			p.pos++
		case '{':
			mn, mx, ok := p.tryBrace()
			if !ok {
				return atom
			}
			min, max = mn, mx
		default:
			return atom
		}
		if isQuantifiable(atom) == false {
			p.errf("quantifier following nothing")
		}
		lazy := false
		if p.more() && p.peek() == '?' {
			lazy = true
			p.pos++
		}
		if max != -1 && min > max {
			p.errf("illegal {x,y} with x > y")
		}
		atom = &node{kind: nRepeat, subs: []*node{atom}, min: min, max: max, lazy: lazy}
		// check nested repetition
		p.skipSpace()
		if p.more() {
			c2 := p.peek()
			if c2 == '*' || c2 == '+' || c2 == '?' {
				p.errf("nested quantifier '%c'", c2)
			}
			if c2 == '{' {
				save := p.pos
				if _, _, ok := p.tryBrace(); ok {
					p.pos = save
					p.errf("nested quantifier '{'")
				}
				p.pos = save
			}
		}
		return atom
	}
}

func isQuantifiable(n *node) bool {
	return true
}

func (p *parser) tryBrace() (int, int, bool) {
	save := p.pos
	p.pos++ // {
	readNum := func() (int, bool) {
		start := p.pos
		for p.more() && p.peek() >= '0' && p.peek() <= '9' {
			p.pos++
		}
		if start == p.pos {
			return 0, false
		}
		v, err := strconv.Atoi(string(p.src[start:p.pos]))
		if err != nil {
			p.errf("capture group number out of range")
		}
		return v, true
	}
	mn, ok := readNum()
	if !ok {
		p.pos = save
		return 0, 0, false
	}
	mx := mn
	if p.more() && p.peek() == ',' {
		p.pos++
		if p.more() && p.peek() == '}' {
			mx = -1
		} else {
			v, ok := readNum()
			if !ok {
				p.pos = save
				return 0, 0, false
			}
			mx = v
		}
	}
	if !p.more() || p.peek() != '}' {
		p.pos = save
		return 0, 0, false
	}
	p.pos++
	return mn, mx, true
}

func (p *parser) fold() bool { return p.flags&FlagIgnoreCase != 0 }

func (p *parser) charNode(c rune) *node {
	return &node{kind: nChar, ch: c, fold: p.fold()}
}

func (p *parser) parseAtom() *node {
	c := p.peek()
	switch c {
	case '(':
		return p.parseGroup()
	case '[':
		p.pos++
		set := p.parseClass()
		return &node{kind: nSet, set: set, fold: p.fold()}
	case '.':
		p.pos++
		return &node{kind: nAny, dotAll: p.flags&FlagSingleline != 0}
	case '^':
		p.pos++
		if p.flags&FlagMultiline != 0 {
			return &node{kind: nBol, multi: true}
		}
		return &node{kind: nBeginText}
	case '$':
		p.pos++
		return &node{kind: nEol, multi: p.flags&FlagMultiline != 0}
	case '\\':
		return p.parseEscape()
	case '*', '+', '?':
		p.errf("quantifier '%c' following nothing", c)
	case '{':
		save := p.pos
		if _, _, ok := p.tryBrace(); ok {
			p.pos = save
			p.errf("quantifier '{' following nothing")
		}
		p.pos = save + 1
		return p.charNode('{')
	}
	p.pos++
	return p.charNode(c)
}

func (p *parser) parseGroupName(end rune) string {
	start := p.pos
	for p.more() && p.peek() != end {
		p.pos++
	}
	if !p.more() {
		p.errf("invalid group name")
	}
	name := string(p.src[start:p.pos])
	p.pos++
	return name
}

func (p *parser) parseGroup() *node {
	p.pos++ // (
	savedFlags := p.flags
	defer func() { p.flags = savedFlags }()
	if p.peek() == '?' {
		p.pos++
		c := p.peek()
		switch c {
		case ':':
			p.pos++
			sub := p.parseAlt()
			p.expectClose()
			return &node{kind: nNonCap, subs: []*node{sub}}
		case '=':
			p.pos++
			sub := p.parseAlt()
			p.expectClose()
			return &node{kind: nLookahead, subs: []*node{sub}}
		case '!':
			p.pos++
			sub := p.parseAlt()
			p.expectClose()
			return &node{kind: nNegLookahead, subs: []*node{sub}}
		case '>':
			p.pos++
			sub := p.parseAlt()
			p.expectClose()
			return &node{kind: nAtomic, subs: []*node{sub}}
		case '#':
			for p.more() && p.peek() != ')' {
				p.pos++
			}
			if !p.more() {
				p.errf("missing closing )")
			}
			p.pos++
			return nil
		case '(':
			// conditional
			p.pos++
			// group name/number?
			start := p.pos
			for p.more() && p.peek() != ')' {
				p.pos++
			}
			name := string(p.src[start:p.pos])
			grp := -1
			if num, err := strconv.Atoi(name); err == nil {
				grp = num
			} else if g, ok := p.names[name]; ok {
				grp = g
			}
			var cond *node
			if grp < 0 {
				p.pos = start - 1
				// expression: parse as lookahead
				p.pos++
				var kind nodeKind = nLookahead
				if p.peek() == '?' && (p.peekAt(1) == '=' || p.peekAt(1) == '!') {
					if p.peekAt(1) == '!' {
						kind = nNegLookahead
					}
					p.pos += 2
				} else if p.peek() == '?' && p.peekAt(1) == '<' && (p.peekAt(2) == '=' || p.peekAt(2) == '!') {
					kind = nLookbehind
					if p.peekAt(2) == '!' {
						kind = nNegLookbehind
					}
					p.pos += 3
				}
				sub := p.parseAlt()
				p.expectClose()
				cond = &node{kind: kind, subs: []*node{sub}}
			} else {
				p.pos++ // )
			}
			yes := p.parseConcat()
			var no *node
			if p.more() && p.peek() == '|' {
				p.pos++
				no = p.parseConcat()
				if p.more() && p.peek() == '|' {
					p.errf("too many | in (?()|)")
				}
			} else {
				no = &node{kind: nEmpty}
			}
			p.expectClose()
			return &node{kind: nCond, condGrp: grp, condExpr: cond, subs: []*node{yes, no}}
		case '<', '\'':
			end := rune('>')
			if c == '\'' {
				end = '\''
			}
			if c == '<' && (p.peekAt(1) == '=' || p.peekAt(1) == '!') {
				neg := p.peekAt(1) == '!'
				p.pos += 2
				sub := p.parseAlt()
				p.expectClose()
				if neg {
					return &node{kind: nNegLookbehind, subs: []*node{sub}}
				}
				return &node{kind: nLookbehind, subs: []*node{sub}}
			}
			p.pos++
			name := p.parseGroupName(end)
			if k := strings.IndexByte(name, '-'); k >= 0 {
				name = name[:k]
			}
			if name == "" {
				p.errf("invalid group name: group names must begin with a word character and have a matching terminator")
			}
			idx := p.names[name]
			sub := p.parseAlt()
			p.expectClose()
			return &node{kind: nGroup, group: idx, subs: []*node{sub}}
		default:
			// inline options
			on := true
			nf := p.flags
			start := p.pos
			for p.more() {
				ch := p.peek()
				if ch == '-' {
					on = false
				} else if f := optFlag(ch); f != 0 {
					if on {
						nf |= f
					} else {
						nf &^= f
					}
				} else {
					break
				}
				p.pos++
			}
			if p.more() && p.peek() == ')' && p.pos > start {
				p.pos++
				savedFlags = nf // keep for remainder of enclosing group
				p.flags = nf
				return nil
			}
			if p.more() && p.peek() == ':' && p.pos > start {
				p.pos++
				p.flags = nf
				sub := p.parseAlt()
				p.expectClose()
				return &node{kind: nNonCap, subs: []*node{sub}}
			}
			p.pos = start
			p.errf("unrecognized grouping construct: (?%s", string(p.src[start:min(start+1, len(p.src))]))
		}
	}
	if p.flags&FlagExplicitCapture != 0 {
		sub := p.parseAlt()
		p.expectClose()
		return &node{kind: nNonCap, subs: []*node{sub}}
	}
	p.capCount++
	idx := p.capCount
	sub := p.parseAlt()
	p.expectClose()
	return &node{kind: nGroup, group: idx, subs: []*node{sub}}
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func (p *parser) expectClose() {
	if !p.more() || p.peek() != ')' {
		p.errf("missing closing )")
	}
	p.pos++
}

func isWordRune(r rune) bool {
	if r < 128 {
		return r == '_' || (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') || (r >= '0' && r <= '9')
	}
	return unicode.IsLetter(r) || unicode.Is(unicode.Mn, r) || unicode.Is(unicode.Nd, r) || unicode.Is(unicode.Pc, r)
}

func isSpaceRune(r rune) bool {
	switch r {
	case ' ', '\t', '\n', '\r', '\f', '\v', 0x85:
		return true
	}
	if r < 128 {
		return false
	}
	return unicode.Is(unicode.Z, r)
}

func isDigitRune(r rune) bool {
	if r < 128 {
		return r >= '0' && r <= '9'
	}
	return unicode.Is(unicode.Nd, r)
}

func (p *parser) parseEscape() *node {
	p.pos++ // backslash
	if !p.more() {
		p.errf("illegal \\ at end of pattern")
	}
	c := p.peek()
	switch c {
	case 'A':
		p.pos++
		return &node{kind: nBeginText}
	case 'Z':
		p.pos++
		return &node{kind: nEndTextZ}
	case 'z':
		p.pos++
		return &node{kind: nEndText}
	case 'G':
		p.pos++
		return &node{kind: nStartPos}
	case 'b':
		p.pos++
		return &node{kind: nWordB}
	case 'B':
		p.pos++
		return &node{kind: nNonWordB}
	case 'd', 'D', 'w', 'W', 's', 'S', 'p', 'P':
		set := &charSet{}
		p.pos++
		p.addClassEscape(set, c)
		return &node{kind: nSet, set: set, fold: p.fold()}
	case 'k':
		p.pos++
		if p.peek() == '<' || p.peek() == '\'' {
			end := rune('>')
			if p.peek() == '\'' {
				end = '\''
			}
			p.pos++
			name := p.parseGroupName(end)
			idx, ok := p.names[name]
			if !ok {
				if num, err := strconv.Atoi(name); err == nil && num <= p.numCaps {
					idx = num
				} else {
					p.errf("reference to undefined group name %s", name)
				}
			}
			return &node{kind: nBackref, group: idx, fold: p.fold()}
		}
		p.errf("malformed \\k<...> named back reference")
	}
	if c >= '1' && c <= '9' {
		start := p.pos
		for p.more() && p.peek() >= '0' && p.peek() <= '9' {
			p.pos++
		}
		num, _ := strconv.Atoi(string(p.src[start:p.pos]))
		if num <= p.numCaps {
			return &node{kind: nBackref, group: num, fold: p.fold()}
		}
		// try single digit
		p.pos = start + 1
		num = int(c - '0')
		if num <= p.numCaps {
			return &node{kind: nBackref, group: num, fold: p.fold()}
		}
		p.errf("reference to undefined group number %d", num)
	}
	r := p.parseCharEscape(false)
	return p.charNode(r)
}

// parseCharEscape parses an escape producing a single char; p.pos at the char after backslash.
func (p *parser) parseCharEscape(inClass bool) rune {
	c := p.peek()
	p.pos++
	switch c {
	case 'n':
		return '\n'
	case 't':
		return '\t'
	case 'r':
		return '\r'
	case 'f':
		return '\f'
	case 'v':
		return '\v'
	case 'a':
		return 7
	case 'e':
		return 27
	case 'b':
		if inClass {
			return 8
		}
	case '0', '1', '2', '3', '4', '5', '6', '7':
		// octal, up to 3 digits
		p.pos--
		v := 0
		n := 0
		for n < 3 && p.more() && p.peek() >= '0' && p.peek() <= '7' {
			v = v*8 + int(p.peek()-'0')
			p.pos++
			n++
		}
		return rune(v & 0xff)
	case 'x':
		if p.peek() == '{' {
			p.pos++
			start := p.pos
			for p.more() && p.peek() != '}' {
				p.pos++
			}
			v, err := strconv.ParseUint(string(p.src[start:p.pos]), 16, 32)
			if err != nil || !p.more() {
				p.errf("insufficient hexadecimal digits")
			}
			p.pos++
			return rune(v)
		}
		return p.hex(2)
	case 'u':
		return p.hex(4)
	case 'c':
		if !p.more() {
			p.errf("missing control character")
		}
		ch := p.peek()
		p.pos++
		if ch >= 'a' && ch <= 'z' {
			ch -= 'a' - 'A'
		}
		ch -= '@'
		if ch < 0 || ch >= ' ' {
			p.errf("unrecognized control character")
		}
		return ch
	}
	if (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c == '_' {
		p.errf("unrecognized escape sequence \\%c", c)
	}
	return c
}

func (p *parser) hex(n int) rune {
	v := 0
	for i := 0; i < n; i++ {
		if !p.more() {
			p.errf("insufficient hexadecimal digits")
		}
		c := p.peek()
		var d int
		switch {
		case c >= '0' && c <= '9':
			d = int(c - '0')
		case c >= 'a' && c <= 'f':
			d = int(c-'a') + 10
		case c >= 'A' && c <= 'F':
			d = int(c-'A') + 10
		default:
			p.errf("insufficient hexadecimal digits")
		}
		v = v*16 + d
		p.pos++
	}
	return rune(v)
}

func (p *parser) addClassEscape(set *charSet, c rune) {
	switch c {
	case 'd':
		set.items = append(set.items, classItem{fn: isDigitRune})
	case 'D':
		set.items = append(set.items, classItem{fn: isDigitRune, neg: true})
	case 'w':
		set.items = append(set.items, classItem{fn: isWordRune})
	case 'W':
		set.items = append(set.items, classItem{fn: isWordRune, neg: true})
	case 's':
		set.items = append(set.items, classItem{fn: isSpaceRune})
	case 'S':
		set.items = append(set.items, classItem{fn: isSpaceRune, neg: true})
	case 'p', 'P':
		if p.peek() != '{' {
			p.errf("incomplete \\p{X} character escape")
		}
		p.pos++
		start := p.pos
		for p.more() && p.peek() != '}' {
			p.pos++
		}
		if !p.more() {
			p.errf("incomplete \\p{X} character escape")
		}
		name := string(p.src[start:p.pos])
		p.pos++
		tab := lookupCategory(name)
		if tab == nil {
			p.errf("unknown unicode category, script, or property '%s'", name)
		}
		set.items = append(set.items, classItem{table: tab, neg: c == 'P'})
	}
}

func lookupCategory(name string) []*unicode.RangeTable {
	if name == "Any" {
		return []*unicode.RangeTable{{R16: []unicode.Range16{{0, 0xffff, 1}}, R32: []unicode.Range32{{0x10000, 0x10ffff, 1}}}}
	}
	if t, ok := unicode.Categories[name]; ok {
		return []*unicode.RangeTable{t}
	}
	if t, ok := unicode.Scripts[name]; ok {
		return []*unicode.RangeTable{t}
	}
	if strings.HasPrefix(name, "Is") {
		if t, ok := blocks[name[2:]]; ok {
			return []*unicode.RangeTable{t}
		}
		if t, ok := unicode.Scripts[name[2:]]; ok {
			return []*unicode.RangeTable{t}
		}
	}
	if t, ok := unicode.Properties[name]; ok {
		return []*unicode.RangeTable{t}
	}
	return nil
}

var blocks = map[string]*unicode.RangeTable{
	"BasicLatin":         {R16: []unicode.Range16{{0x0000, 0x007F, 1}}},
	"Latin-1Supplement":  {R16: []unicode.Range16{{0x0080, 0x00FF, 1}}},
	"LatinExtended-A":    {R16: []unicode.Range16{{0x0100, 0x017F, 1}}},
	"LatinExtended-B":    {R16: []unicode.Range16{{0x0180, 0x024F, 1}}},
	"Greek":              {R16: []unicode.Range16{{0x0370, 0x03FF, 1}}},
	"GreekandCoptic":     {R16: []unicode.Range16{{0x0370, 0x03FF, 1}}},
	"Cyrillic":           {R16: []unicode.Range16{{0x0400, 0x04FF, 1}}},
	"CJKUnifiedIdeographs": {R16: []unicode.Range16{{0x4E00, 0x9FFF, 1}}},
}

// parseClass parses after '['.
func (p *parser) parseClass() *charSet {
	set := &charSet{}
	if p.peek() == '^' {
		set.neg = true
		p.pos++
	}
	first := true
	for {
		if !p.more() {
			p.errf("unterminated [] set")
		}
		c := p.peek()
		if c == ']' && !first {
			p.pos++
			break
		}
		first = false
		// subtraction
		if c == '-' && p.peekAt(1) == '[' && len(set.items)+len(set.ranges) > 0 {
			p.pos += 2
			sub := p.parseClass()
			set.sub = sub
			if !p.more() || p.peek() != ']' {
				p.errf("a subtraction must be the last element in a character class")
			}
			p.pos++
			break
		}
		var lo rune
		isChar := true
		if c == '\\' {
			p.pos++
			if !p.more() {
				p.errf("illegal \\ at end of pattern")
			}
			e := p.peek()
			switch e {
			case 'd', 'D', 'w', 'W', 's', 'S', 'p', 'P':
				p.pos++
				p.addClassEscape(set, e)
				isChar = false
			default:
				lo = p.parseCharEscape(true)
			}
		} else if c == '[' {
			p.pos++
			lo = '['
			if p.peek() == ':' {
				save := p.pos
				p.pos++
				for p.more() && isWordRune(p.peek()) {
					p.pos++
				}
				if p.peek() == ':' && p.peekAt(1) == ']' {
					p.pos += 2
				} else {
					p.pos = save
				}
			}
		} else {
			p.pos++
			lo = c
		}
		if !isChar {
			// a following '-' is literal
			continue
		}
		// range?
		if p.peek() == '-' && p.peekAt(1) != ']' && p.more() && p.pos+1 < len(p.src) {
			if p.peekAt(1) == '[' {
				// subtraction follows
				set.ranges = append(set.ranges, runeRange{lo, lo})
				continue
			}
			p.pos++ // -
			hc := p.peek()
			var hi rune
			if hc == '\\' {
				p.pos++
				e := p.peek()
				switch e {
				case 'd', 'D', 'w', 'W', 's', 'S', 'p', 'P':
					p.errf("cannot include class \\%c in character range", e)
				}
				hi = p.parseCharEscape(true)
			} else {
				p.pos++
				hi = hc
			}
			if hi < lo {
				p.errf("[x-y] range in reverse order")
			}
			set.ranges = append(set.ranges, runeRange{lo, hi})
			continue
		}
		set.ranges = append(set.ranges, runeRange{lo, lo})
	}
	set.prepare()
	return set
}
EOF
echo done"}

actions.command:
cd /workspace/internal/regex && cat > syntax.go <<'EOF'
package regex

import (
	"fmt"
	"strconv"
	"strings"
	"unicode"
)

// Flags
const (
	FlagIgnoreCase = 1 << iota
	FlagMultiline
	FlagSingleline
	FlagExplicitCapture
	FlagIgnoreSpace
)

type nodeKind int

const (
	nEmpty nodeKind = iota
	nChar
	nSet
	nAny
	nBol
	nEol
	nBeginText
	nEndTextZ
	nEndText
	nStartPos
	nWordB
	nNonWordB
	nConcat
	nAlt
	nRepeat
	nGroup
	nNonCap
	nLookahead
	nNegLookahead
	nLookbehind
	nNegLookbehind
	nAtomic
	nBackref
	nCond
	nFail
)

type node struct {
	kind     nodeKind
	ch       rune
	fold     bool // ignore case
	set      *charSet
	dotAll   bool
	multi    bool
	subs     []*node
	min, max int // repeat; max -1 = inf
	lazy     bool
	group    int
	condGrp  int // for conditional: group number or -1 for expression
	condExpr *node
}

type parser struct {
	src       []rune
	pos       int
	flags     int
	capCount  int
	names     map[string]int
	nameOrder []string
	numCaps   int
	pattern   string
}

type Error struct {
	Msg     string
	Pattern string
}

func (e *Error) Error() string {
	return fmt.Sprintf("error parsing regexp: %s in `%s`", e.Msg, e.Pattern)
}

func (p *parser) errf(format string, args ...interface{}) {
	panic(&Error{Msg: fmt.Sprintf(format, args...), Pattern: p.pattern})
}

func (p *parser) more() bool { return p.pos < len(p.src) }
func (p *parser) peek() rune {
	if p.pos < len(p.src) {
		return p.src[p.pos]
	}
	return 0
}
func (p *parser) peekAt(i int) rune {
	if p.pos+i < len(p.src) {
		return p.src[p.pos+i]
	}
	return 0
}

// prescan counts unnamed capture groups and collects names to emulate .NET numbering.
func (p *parser) prescan() {
	src := p.src
	flags := p.flags
	unnamed := 0
	var names []string
	inClass := false
	type fstack struct{ flags int }
	var stack []int
	for i := 0; i < len(src); i++ {
		c := src[i]
		if c == '\\' {
			i++
			continue
		}
		if inClass {
			if c == ']' {
				inClass = false
			}
			continue
		}
		if flags&FlagIgnoreSpace != 0 && c == '#' {
			for i < len(src) && src[i] != '\n' {
				i++
			}
			continue
		}
		switch c {
		case '[':
			inClass = true
			// handle []...] and [^]...]
			if i+1 < len(src) && src[i+1] == '^' {
				i++
			}
			if i+1 < len(src) && src[i+1] == ']' {
				i++
			}
		case '(':
			stack = append(stack, flags)
			if i+1 < len(src) && src[i+1] == '?' {
				// named?
				if i+2 < len(src) && (src[i+2] == '<' || src[i+2] == '\'') {
					if i+3 < len(src) && (src[i+3] == '=' || src[i+3] == '!') {
						continue
					}
					end := byte('>')
					if src[i+2] == '\'' {
						end = '\''
					}
					j := i + 3
					for j < len(src) && src[j] != rune(end) {
						j++
					}
					name := string(src[i+3 : j])
					if k := strings.IndexByte(name, '-'); k >= 0 {
						name = name[:k]
					}
					if name != "" {
						names = append(names, name)
					}
					continue
				}
				if i+2 < len(src) && src[i+2] == '#' {
					// comment
					for i < len(src) && src[i] != ')' {
						i++
					}
					stack = stack[:len(stack)-1]
					continue
				}
				// inline options
				j := i + 2
				on := true
				nf := flags
				for j < len(src) {
					ch := src[j]
					if ch == '-' {
						on = false
					} else if f := optFlag(ch); f != 0 {
						if on {
							nf |= f
						} else {
							nf &^= f
						}
					} else {
						break
					}
					j++
				}
				if j < len(src) && src[j] == ')' {
					// applies to the rest of the enclosing group
					stack = stack[:len(stack)-1]
					flags = nf
					i = j
				} else if j < len(src) && src[j] == ':' {
					stack[len(stack)-1] = flags
					flags = nf
					i = j
				}
				continue
			}
			if flags&FlagExplicitCapture == 0 {
				unnamed++
			}
		case ')':
			if len(stack) > 0 {
				flags = stack[len(stack)-1]
				stack = stack[:len(stack)-1]
			}
		}
	}
	p.capCount = unnamed
	p.names = map[string]int{}
	next := unnamed + 1
	for _, n := range names {
		if _, ok := p.names[n]; ok {
			continue
		}
		if num, err := strconv.Atoi(n); err == nil {
			p.names[n] = num
			continue
		}
		p.names[n] = next
		next++
	}
	p.numCaps = next - 1
	for _, v := range p.names {
		if v > p.numCaps {
			p.numCaps = v
		}
	}
}

func optFlag(c rune) int {
	switch c {
	case 'i':
		return FlagIgnoreCase
	case 'm':
		return FlagMultiline
	case 's':
		return FlagSingleline
	case 'n':
		return FlagExplicitCapture
	case 'x':
		return FlagIgnoreSpace
	}
	return 0
}

func parse(pattern string, flags int) (n *node, ncap int, names map[string]int, err error) {
	p := &parser{src: []rune(pattern), flags: flags, pattern: pattern}
	defer func() {
		if r := recover(); r != nil {
			if e, ok := r.(*Error); ok {
				err = e
				return
			}
			panic(r)
		}
	}()
	p.prescan()
	p.flags = flags
	p.capCount = 0
	n = p.parseAlt()
	if p.more() {
		if p.peek() == ')' {
			p.errf("too many )'s")
		}
		p.errf("unexpected character")
	}
	return n, p.numCaps, p.names, nil
}

func (p *parser) skipSpace() {
	if p.flags&FlagIgnoreSpace == 0 {
		return
	}
	for p.more() {
		c := p.peek()
		if c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f' || c == '\v' {
			p.pos++
			continue
		}
		if c == '#' {
			for p.more() && p.peek() != '\n' {
				p.pos++
			}
			continue
		}
		break
	}
}

func (p *parser) parseAlt() *node {
	saved := p.flags
	var alts []*node
	for {
		alts = append(alts, p.parseConcat())
		if p.more() && p.peek() == '|' {
			p.pos++
			continue
		}
		break
	}
	p.flags = saved
	if len(alts) == 1 {
		return alts[0]
	}
	return &node{kind: nAlt, subs: alts}
}

func (p *parser) parseConcat() *node {
	var items []*node
	for {
		p.skipSpace()
		if !p.more() {
			break
		}
		c := p.peek()
		if c == '|' || c == ')' {
			break
		}
		atom := p.parseAtom()
		if atom == nil {
			continue
		}
		atom = p.parseQuant(atom)
		items = append(items, atom)
	}
	if len(items) == 0 {
		return &node{kind: nEmpty}
	}
	if len(items) == 1 {
		return items[0]
	}
	return &node{kind: nConcat, subs: items}
}

func (p *parser) parseQuant(atom *node) *node {
	for {
		p.skipSpace()
		if !p.more() {
			return atom
		}
		c := p.peek()
		min, max := -1, -1
		switch c {
		case '*':
			min, max = 0, -1
			p.pos++
		case '+':
			min, max = 1, -1
			p.pos++
		case '?':
			min, max = 0, 1
			p.pos++
		case '{':
			mn, mx, ok := p.tryBrace()
			if !ok {
				return atom
			}
			min, max = mn, mx
		default:
			return atom
		}
		if isQuantifiable(atom) == false {
			p.errf("quantifier following nothing")
		}
		lazy := false
		if p.more() && p.peek() == '?' {
			lazy = true
			p.pos++
		}
		if max != -1 && min > max {
			p.errf("illegal {x,y} with x > y")
		}
		atom = &node{kind: nRepeat, subs: []*node{atom}, min: min, max: max, lazy: lazy}
		// check nested repetition
		p.skipSpace()
		if p.more() {
			c2 := p.peek()
			if c2 == '*' || c2 == '+' || c2 == '?' {
				p.errf("nested quantifier '%c'", c2)
			}
			if c2 == '{' {
				save := p.pos
				if _, _, ok := p.tryBrace(); ok {
					p.pos = save
					p.errf("nested quantifier '{'")
				}
				p.pos = save
			}
		}
		return atom
	}
}

func isQuantifiable(n *node) bool {
	return true
}

func (p *parser) tryBrace() (int, int, bool) {
	save := p.pos
	p.pos++ // {
	readNum := func() (int, bool) {
		start := p.pos
		for p.more() && p.peek() >= '0' && p.peek() <= '9' {
			p.pos++
		}
		if start == p.pos {
			return 0, false
		}
		v, err := strconv.Atoi(string(p.src[start:p.pos]))
		if err != nil {
			p.errf("capture group number out of range")
		}
		return v, true
	}
	mn, ok := readNum()
	if !ok {
		p.pos = save
		return 0, 0, false
	}
	mx := mn
	if p.more() && p.peek() == ',' {
		p.pos++
		if p.more() && p.peek() == '}' {
			mx = -1
		} else {
			v, ok := readNum()
			if !ok {
				p.pos = save
				return 0, 0, false
			}
			mx = v
		}
	}
	if !p.more() || p.peek() != '}' {
		p.pos = save
		return 0, 0, false
	}
	p.pos++
	return mn, mx, true
}

func (p *parser) fold() bool { return p.flags&FlagIgnoreCase != 0 }

func (p *parser) charNode(c rune) *node {
	return &node{kind: nChar, ch: c, fold: p.fold()}
}

func (p *parser) parseAtom() *node {
	c := p.peek()
	switch c {
	case '(':
		return p.parseGroup()
	case '[':
		p.pos++
		set := p.parseClass()
		return &node{kind: nSet, set: set, fold: p.fold()}
	case '.':
		p.pos++
		return &node{kind: nAny, dotAll: p.flags&FlagSingleline != 0}
	case '^':
		p.pos++
		if p.flags&FlagMultiline != 0 {
			return &node{kind: nBol, multi: true}
		}
		return &node{kind: nBeginText}
	case '$':
		p.pos++
		return &node{kind: nEol, multi: p.flags&FlagMultiline != 0}
	case '\\':
		return p.parseEscape()
	case '*', '+', '?':
		p.errf("quantifier '%c' following nothing", c)
	case '{':
		save := p.pos
		if _, _, ok := p.tryBrace(); ok {
			p.pos = save
			p.errf("quantifier '{' following nothing")
		}
		p.pos = save + 1
		return p.charNode('{')
	}
	p.pos++
	return p.charNode(c)
}

func (p *parser) parseGroupName(end rune) string {
	start := p.pos
	for p.more() && p.peek() != end {
		p.pos++
	}
	if !p.more() {
		p.errf("invalid group name")
	}
	name := string(p.src[start:p.pos])
	p.pos++
	return name
}

func (p *parser) parseGroup() *node {
	p.pos++ // (
	savedFlags := p.flags
	defer func() { p.flags = savedFlags }()
	if p.peek() == '?' {
		p.pos++
		c := p.peek()
		switch c {
		case ':':
			p.pos++
			sub := p.parseAlt()
			p.expectClose()
			return &node{kind: nNonCap, subs: []*node{sub}}
		case '=':
			p.pos++
			sub := p.parseAlt()
			p.expectClose()
			return &node{kind: nLookahead, subs: []*node{sub}}
		case '!':
			p.pos++
			sub := p.parseAlt()
			p.expectClose()
			return &node{kind: nNegLookahead, subs: []*node{sub}}
		case '>':
			p.pos++
			sub := p.parseAlt()
			p.expectClose()
			return &node{kind: nAtomic, subs: []*node{sub}}
		case '#':
			for p.more() && p.peek() != ')' {
				p.pos++
			}
			if !p.more() {
				p.errf("missing closing )")
			}
			p.pos++
			return nil
		case '(':
			// conditional
			p.pos++
			// group name/number?
			start := p.pos
			for p.more() && p.peek() != ')' {
				p.pos++
			}
			name := string(p.src[start:p.pos])
			grp := -1
			if num, err := strconv.Atoi(name); err == nil {
				grp = num
			} else if g, ok := p.names[name]; ok {
				grp = g
			}
			var cond *node
			if grp < 0 {
				p.pos = start - 1
				// expression: parse as lookahead
				p.pos++
				var kind nodeKind = nLookahead
				if p.peek() == '?' && (p.peekAt(1) == '=' || p.peekAt(1) == '!') {
					if p.peekAt(1) == '!' {
						kind = nNegLookahead
					}
					p.pos += 2
				} else if p.peek() == '?' && p.peekAt(1) == '<' && (p.peekAt(2) == '=' || p.peekAt(2) == '!') {
					kind = nLookbehind
					if p.peekAt(2) == '!' {
						kind = nNegLookbehind
					}
					p.pos += 3
				}
				sub := p.parseAlt()
				p.expectClose()
				cond = &node{kind: kind, subs: []*node{sub}}
			} else {
				p.pos++ // )
			}
			yes := p.parseConcat()
			var no *node
			if p.more() && p.peek() == '|' {
				p.pos++
				no = p.parseConcat()
				if p.more() && p.peek() == '|' {
					p.errf("too many | in (?()|)")
				}
			} else {
				no = &node{kind: nEmpty}
			}
			p.expectClose()
			return &node{kind: nCond, condGrp: grp, condExpr: cond, subs: []*node{yes, no}}
		case '<', '\'':
			end := rune('>')
			if c == '\'' {
				end = '\''
			}
			if c == '<' && (p.peekAt(1) == '=' || p.peekAt(1) == '!') {
				neg := p.peekAt(1) == '!'
				p.pos += 2
				sub := p.parseAlt()
				p.expectClose()
				if neg {
					return &node{kind: nNegLookbehind, subs: []*node{sub}}
				}
				return &node{kind: nLookbehind, subs: []*node{sub}}
			}
			p.pos++
			name := p.parseGroupName(end)
			if k := strings.IndexByte(name, '-'); k >= 0 {
				name = name[:k]
			}
			if name == "" {
				p.errf("invalid group name: group names must begin with a word character and have a matching terminator")
			}
			idx := p.names[name]
			sub := p.parseAlt()
			p.expectClose()
			return &node{kind: nGroup, group: idx, subs: []*node{sub}}
		default:
			// inline options
			on := true
			nf := p.flags
			start := p.pos
			for p.more() {
				ch := p.peek()
				if ch == '-' {
					on = false
				} else if f := optFlag(ch); f != 0 {
					if on {
						nf |= f
					} else {
						nf &^= f
					}
				} else {
					break
				}
				p.pos++
			}
			if p.more() && p.peek() == ')' && p.pos > start {
				p.pos++
				savedFlags = nf // keep for remainder of enclosing group
				p.flags = nf
				return nil
			}
			if p.more() && p.peek() == ':' && p.pos > start {
				p.pos++
				p.flags = nf
				sub := p.parseAlt()
				p.expectClose()
				return &node{kind: nNonCap, subs: []*node{sub}}
			}
			p.pos = start
			p.errf("unrecognized grouping construct: (?%s", string(p.src[start:min(start+1, len(p.src))]))
		}
	}
	if p.flags&FlagExplicitCapture != 0 {
		sub := p.parseAlt()
		p.expectClose()
		return &node{kind: nNonCap, subs: []*node{sub}}
	}
	p.capCount++
	idx := p.capCount
	sub := p.parseAlt()
	p.expectClose()
	return &node{kind: nGroup, group: idx, subs: []*node{sub}}
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func (p *parser) expectClose() {
	if !p.more() || p.peek() != ')' {
		p.errf("missing closing )")
	}
	p.pos++
}

func isWordRune(r rune) bool {
	if r < 128 {
		return r == '_' || (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') || (r >= '0' && r <= '9')
	}
	return unicode.IsLetter(r) || unicode.Is(unicode.Mn, r) || unicode.Is(unicode.Nd, r) || unicode.Is(unicode.Pc, r)
}

func isSpaceRune(r rune) bool {
	switch r {
	case ' ', '\t', '\n', '\r', '\f', '\v', 0x85:
		return true
	}
	if r < 128 {
		return false
	}
	return unicode.Is(unicode.Z, r)
}

func isDigitRune(r rune) bool {
	if r < 128 {
		return r >= '0' && r <= '9'
	}
	return unicode.Is(unicode.Nd, r)
}

func (p *parser) parseEscape() *node {
	p.pos++ // backslash
	if !p.more() {
		p.errf("illegal \\ at end of pattern")
	}
	c := p.peek()
	switch c {
	case 'A':
		p.pos++
		return &node{kind: nBeginText}
	case 'Z':
		p.pos++
		return &node{kind: nEndTextZ}
	case 'z':
		p.pos++
		return &node{kind: nEndText}
	case 'G':
		p.pos++
		return &node{kind: nStartPos}
	case 'b':
		p.pos++
		return &node{kind: nWordB}
	case 'B':
		p.pos++
		return &node{kind: nNonWordB}
	case 'd', 'D', 'w', 'W', 's', 'S', 'p', 'P':
		set := &charSet{}
		p.pos++
		p.addClassEscape(set, c)
		return &node{kind: nSet, set: set, fold: p.fold()}
	case 'k':
		p.pos++
		if p.peek() == '<' || p.peek() == '\'' {
			end := rune('>')
			if p.peek() == '\'' {
				end = '\''
			}
			p.pos++
			name := p.parseGroupName(end)
			idx, ok := p.names[name]
			if !ok {
				if num, err := strconv.Atoi(name); err == nil && num <= p.numCaps {
					idx = num
				} else {
					p.errf("reference to undefined group name %s", name)
				}
			}
			return &node{kind: nBackref, group: idx, fold: p.fold()}
		}
		p.errf("malformed \\k<...> named back reference")
	}
	if c >= '1' && c <= '9' {
		start := p.pos
		for p.more() && p.peek() >= '0' && p.peek() <= '9' {
			p.pos++
		}
		num, _ := strconv.Atoi(string(p.src[start:p.pos]))
		if num <= p.numCaps {
			return &node{kind: nBackref, group: num, fold: p.fold()}
		}
		// try single digit
		p.pos = start + 1
		num = int(c - '0')
		if num <= p.numCaps {
			return &node{kind: nBackref, group: num, fold: p.fold()}
		}
		p.errf("reference to undefined group number %d", num)
	}
	r := p.parseCharEscape(false)
	return p.charNode(r)
}

// parseCharEscape parses an escape producing a single char; p.pos at the char after backslash.
func (p *parser) parseCharEscape(inClass bool) rune {
	c := p.peek()
	p.pos++
	switch c {
	case 'n':
		return '\n'
	case 't':
		return '\t'
	case 'r':
		return '\r'
	case 'f':
		return '\f'
	case 'v':
		return '\v'
	case 'a':
		return 7
	case 'e':
		return 27
	case 'b':
		if inClass {
			return 8
		}
	case '0', '1', '2', '3', '4', '5', '6', '7':
		// octal, up to 3 digits
		p.pos--
		v := 0
		n := 0
		for n < 3 && p.more() && p.peek() >= '0' && p.peek() <= '7' {
			v = v*8 + int(p.peek()-'0')
			p.pos++
			n++
		}
		return rune(v & 0xff)
	case 'x':
		if p.peek() == '{' {
			p.pos++
			start := p.pos
			for p.more() && p.peek() != '}' {
				p.pos++
			}
			v, err := strconv.ParseUint(string(p.src[start:p.pos]), 16, 32)
			if err != nil || !p.more() {
				p.errf("insufficient hexadecimal digits")
			}
			p.pos++
			return rune(v)
		}
		return p.hex(2)
	case 'u':
		return p.hex(4)
	case 'c':
		if !p.more() {
			p.errf("missing control character")
		}
		ch := p.peek()
		p.pos++
		if ch >= 'a' && ch <= 'z' {
			ch -= 'a' - 'A'
		}
		ch -= '@'
		if ch < 0 || ch >= ' ' {
			p.errf("unrecognized control character")
		}
		return ch
	}
	if (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c == '_' {
		p.errf("unrecognized escape sequence \\%c", c)
	}
	return c
}

func (p *parser) hex(n int) rune {
	v := 0
	for i := 0; i < n; i++ {
		if !p.more() {
			p.errf("insufficient hexadecimal digits")
		}
		c := p.peek()
		var d int
		switch {
		case c >= '0' && c <= '9':
			d = int(c - '0')
		case c >= 'a' && c <= 'f':
			d = int(c-'a') + 10
		case c >= 'A' && c <= 'F':
			d = int(c-'A') + 10
		default:
			p.errf("insufficient hexadecimal digits")
		}
		v = v*16 + d
		p.pos++
	}
	return rune(v)
}

func (p *parser) addClassEscape(set *charSet, c rune) {
	switch c {
	case 'd':
		set.items = append(set.items, classItem{fn: isDigitRune})
	case 'D':
		set.items = append(set.items, classItem{fn: isDigitRune, neg: true})
	case 'w':
		set.items = append(set.items, classItem{fn: isWordRune})
	case 'W':
		set.items = append(set.items, classItem{fn: isWordRune, neg: true})
	case 's':
		set.items = append(set.items, classItem{fn: isSpaceRune})
	case 'S':
		set.items = append(set.items, classItem{fn: isSpaceRune, neg: true})
	case 'p', 'P':
		if p.peek() != '{' {
			p.errf("incomplete \\p{X} character escape")
		}
		p.pos++
		start := p.pos
		for p.more() && p.peek() != '}' {
			p.pos++
		}
		if !p.more() {
			p.errf("incomplete \\p{X} character escape")
		}
		name := string(p.src[start:p.pos])
		p.pos++
		tab := lookupCategory(name)
		if tab == nil {
			p.errf("unknown unicode category, script, or property '%s'", name)
		}
		set.items = append(set.items, classItem{table: tab, neg: c == 'P'})
	}
}

func lookupCategory(name string) []*unicode.RangeTable {
	if name == "Any" {
		return []*unicode.RangeTable{{R16: []unicode.Range16{{0, 0xffff, 1}}, R32: []unicode.Range32{{0x10000, 0x10ffff, 1}}}}
	}
	if t, ok := unicode.Categories[name]; ok {
		return []*unicode.RangeTable{t}
	}
	if t, ok := unicode.Scripts[name]; ok {
		return []*unicode.RangeTable{t}
	}
	if strings.HasPrefix(name, "Is") {
		if t, ok := blocks[name[2:]]; ok {
			return []*unicode.RangeTable{t}
		}
		if t, ok := unicode.Scripts[name[2:]]; ok {
			return []*unicode.RangeTable{t}
		}
	}
	if t, ok := unicode.Properties[name]; ok {
		return []*unicode.RangeTable{t}
	}
	return nil
}

var blocks = map[string]*unicode.RangeTable{
	"BasicLatin":         {R16: []unicode.Range16{{0x0000, 0x007F, 1}}},
	"Latin-1Supplement":  {R16: []unicode.Range16{{0x0080, 0x00FF, 1}}},
	"LatinExtended-A":    {R16: []unicode.Range16{{0x0100, 0x017F, 1}}},
	"LatinExtended-B":    {R16: []unicode.Range16{{0x0180, 0x024F, 1}}},
	"Greek":              {R16: []unicode.Range16{{0x0370, 0x03FF, 1}}},
	"GreekandCoptic":     {R16: []unicode.Range16{{0x0370, 0x03FF, 1}}},
	"Cyrillic":           {R16: []unicode.Range16{{0x0400, 0x04FF, 1}}},
	"CJKUnifiedIdeographs": {R16: []unicode.Range16{{0x4E00, 0x9FFF, 1}}},
}

// parseClass parses after '['.
func (p *parser) parseClass() *charSet {
	set := &charSet{}
	if p.peek() == '^' {
		set.neg = true
		p.pos++
	}
	first := true
	for {
		if !p.more() {
			p.errf("unterminated [] set")
		}
		c := p.peek()
		if c == ']' && !first {
			p.pos++
			break
		}
		first = false
		// subtraction
		if c == '-' && p.peekAt(1) == '[' && len(set.items)+len(set.ranges) > 0 {
			p.pos += 2
			sub := p.parseClass()
			set.sub = sub
			if !p.more() || p.peek() != ']' {
				p.errf("a subtraction must be the last element in a character class")
			}
			p.pos++
			break
		}
		var lo rune
		isChar := true
		if c == '\\' {
			p.pos++
			if !p.more() {
				p.errf("illegal \\ at end of pattern")
			}
			e := p.peek()
			switch e {
			case 'd', 'D', 'w', 'W', 's', 'S', 'p', 'P':
				p.pos++
				p.addClassEscape(set, e)
				isChar = false
			default:
				lo = p.parseCharEscape(true)
			}
		} else if c == '[' {
			p.pos++
			lo = '['
			if p.peek() == ':' {
				save := p.pos
				p.pos++
				for p.more() && isWordRune(p.peek()) {
					p.pos++
				}
				if p.peek() == ':' && p.peekAt(1) == ']' {
					p.pos += 2
				} else {
					p.pos = save
				}
			}
		} else {
			p.pos++
			lo = c
		}
		if !isChar {
			// a following '-' is literal
			continue
		}
		// range?
		if p.peek() == '-' && p.peekAt(1) != ']' && p.more() && p.pos+1 < len(p.src) {
			if p.peekAt(1) == '[' {
				// subtraction follows
				set.ranges = append(set.ranges, runeRange{lo, lo})
				continue
			}
			p.pos++ // -
			hc := p.peek()
			var hi rune
			if hc == '\\' {
				p.pos++
				e := p.peek()
				switch e {
				case 'd', 'D', 'w', 'W', 's', 'S', 'p', 'P':
					p.errf("cannot include class \\%c in character range", e)
				}
				hi = p.parseCharEscape(true)
			} else {
				p.pos++
				hi = hc
			}
			if hi < lo {
				p.errf("[x-y] range in reverse order")
			}
			set.ranges = append(set.ranges, runeRange{lo, hi})
			continue
		}
		set.ranges = append(set.ranges, runeRange{lo, lo})
	}
	set.prepare()
	return set
}
EOF
