func (s *charSet) rawContains(r rune) bool {
	in := false
	for _, rg := range s.ranges {
		if r >= rg.lo && r <= rg.hi {
			in = true
			break
		}
	}
	if !in {
		for _, it := range s.items {
			var v bool
			if it.fn != nil {
				v = it.fn(r)
			} else {
				for _, t := range it.table {
					if unicode.Is(t, r) {
						v = true
						break
					}
				}
			}
			if it.neg {
				v = !v
			}
			if v {
				in = true
				break
			}
		}
	}
	if in && s.sub != nil && s.sub.matches(r, false) {
		in = false
	}
	if s.neg {
		in = !in
	}
	return in
}

func (s *charSet) foldContains(r rune) bool {
	// .NET semantic: lowercase(input) tested against lowercased class.
	// Approximate: test r, lower(r), upper(r) against positive set.
	if s.neg {
		s.neg = false
		v := s.foldPositive(r)
		s.neg = true
		return !v
	}
	return s.foldPositive(r)
}

func (s *charSet) foldPositive(r rune) bool {
	if s.rawContains(r) {
		return true
	}
	l := unicode.ToLower(r)
	if l != r && s.rawContains(l) {
		return true
	}
	u := unicode.ToUpper(r)
	if u != r && s.rawContains(u) {
		return true
	}
	// characters whose lowercase equals lower(r)
	for f := unicode.SimpleFold(r); f != r; f = unicode.SimpleFold(f) {
		if unicode.ToLower(f) == l && s.rawContains(f) {
			return true
		}
	}
	return false
}

func (s *charSet) prepare() {
	for r := rune(0); r < 128; r++ {
		if s.rawContains(r) {
			s.ascii[r>>5] |= 1 << (uint(r) & 31)
		}
		if s.foldContains(r) {
			s.asciiFold[r>>5] |= 1 << (uint(r) & 31)
		}
	}
	s.prepared = true
}

func (s *charSet) matches(r rune, fold bool) bool {
	if r < 128 && s.prepared {
		if fold {
			return s.asciiFold[r>>5]&(1<<(uint(r)&31)) != 0
		}
		return s.ascii[r>>5]&(1<<(uint(r)&31)) != 0
	}
	if fold {
		return s.foldContains(r)
	}
	return s.rawContains(r)
}
