package regex

import (
	"unicode"
)

type cont func(pos int) bool

type mfn func(m *machine, pos int, k cont) bool

type machine struct {
	text  []rune
	caps  []int
	start int
}

type Regexp struct {
	pattern  string
	prog     mfn
	ncap     int
	names    map[string]int
	first    firstInfo
	anchorStart bool
}

// Compile compiles a pattern with the given flags.
func Compile(pattern string, flags int) (*Regexp, error) {
	n, ncap, names, err := parse(pattern, flags)
	if err != nil {
		return nil, err
	}
	c := &compiler{}
	re := &Regexp{pattern: pattern, ncap: ncap, names: names}
	re.prog = c.compile(n, func(m *machine, pos int, k cont) bool { return k(pos) })
	re.first = firstOf(n)
	return re, nil
}

func (re *Regexp) NumGroups() int { return re.ncap }
func (re *Regexp) String() string { return re.pattern }

// MatchAt attempts an anchored match at pos. Returns capture positions
// (2*(ncap+1) ints, -1 for unmatched) or nil.
func (re *Regexp) MatchAt(text []rune, pos int) []int {
	if !re.first.nullable {
		if pos >= len(text) {
			return nil
		}
		if !re.first.accept(text[pos]) {
			return nil
		}
	}
	m := &machine{text: text, start: pos}
	m.caps = make([]int, 2*(re.ncap+1))
	for i := range m.caps {
		m.caps[i] = -1
	}
	end := -1
	if re.prog(m, pos, func(p int) bool { end = p; return true }) {
		m.caps[0] = pos
		m.caps[1] = end
		return m.caps
	}
	return nil
}

// FindFrom searches for a match starting at any position >= pos.
