// compile compiles node n followed by next.
func (c *compiler) compile(n *node, next mfn) mfn {
	switch n.kind {
	case nEmpty:
		return next
	case nFail:
		return func(m *machine, pos int, k cont) bool { return false }
	case nChar, nSet, nAny:
		test := singleTest(n)
		return func(m *machine, pos int, k cont) bool {
			if pos < len(m.text) && test(m.text[pos]) {
				return next(m, pos+1, k)
			}
			return false
		}
	case nBol:
		return func(m *machine, pos int, k cont) bool {
			if pos == 0 || m.text[pos-1] == '\n' {
				return next(m, pos, k)
			}
			return false
		}
	case nBeginText:
		return func(m *machine, pos int, k cont) bool {
			if pos == 0 {
				return next(m, pos, k)
			}
			return false
		}
	case nEol:
		if n.multi {
			return func(m *machine, pos int, k cont) bool {
				if pos == len(m.text) || m.text[pos] == '\n' {
					return next(m, pos, k)
				}
				return false
			}
		}
		fallthrough
	case nEndTextZ:
		return func(m *machine, pos int, k cont) bool {
			l := len(m.text)
			if pos == l || (pos == l-1 && m.text[pos] == '\n') {
				return next(m, pos, k)
			}
			return false
		}
	case nEndText:
		return func(m *machine, pos int, k cont) bool {
			if pos == len(m.text) {
				return next(m, pos, k)
			}
			return false
		}
	case nStartPos:
		return func(m *machine, pos int, k cont) bool {
			if pos == m.start {
				return next(m, pos, k)
			}
			return false
		}
	case nWordB, nNonWordB:
		want := n.kind == nWordB
		return func(m *machine, pos int, k cont) bool {
			b := isWordAt(m.text, pos-1) != isWordAt(m.text, pos)
			if b == want {
				return next(m, pos, k)
			}
			return false
		}
	case nConcat:
		f := next
		for i := len(n.subs) - 1; i >= 0; i-- {
			f = c.compile(n.subs[i], f)
		}
		return f
	case nAlt:
		alts := make([]mfn, len(n.subs))
		for i, s := range n.subs {
			alts[i] = c.compile(s, next)
		}
		return func(m *machine, pos int, k cont) bool {
			for _, a := range alts {
				if a(m, pos, k) {
					return true
				}
			}
			return false
		}
	case nNonCap:
		return c.compile(n.subs[0], next)
	case nGroup:
		idx := n.group
		// closing: record capture then continue
		closeFn := func(m *machine, pos int, k cont) bool {
			// start stored temporarily in stack via closure below
			return next(m, pos, k)
		}
		_ = closeFn
		var body mfn
		body = c.compile(n.subs[0], func(m *machine, pos int, k cont) bool {
			// k here is a special continuation carrying start
			return k(pos)
		})
		return func(m *machine, pos int, k cont) bool {
			oldS, oldE := m.caps[2*idx], m.caps[2*idx+1]
			start := pos
			if body(m, pos, func(p int) bool {
				ps, pe := m.caps[2*idx], m.caps[2*idx+1]
				m.caps[2*idx], m.caps[2*idx+1] = start, p
				if next(m, p, k) {
					return true
				}
				m.caps[2*idx], m.caps[2*idx+1] = ps, pe
				return false
			}) {
				return true
			}
			m.caps[2*idx], m.caps[2*idx+1] = oldS, oldE
			return false
		}
	case nLookahead, nNegLookahead:
		body := c.compile(n.subs[0], func(m *machine, pos int, k cont) bool { return k(pos) })
		neg := n.kind == nNegLookahead
		return func(m *machine, pos int, k cont) bool {
			saved := append([]int(nil), m.caps...)
			ok := body(m, pos, func(p int) bool { return true })
			if neg {
				copy(m.caps, saved)
				if ok {
					return false
				}
				return next(m, pos, k)
			}
			if !ok {
				copy(m.caps, saved)
				return false
			}
			if next(m, pos, k) {
				return true
			}
			copy(m.caps, saved)
			return false
		}
	case nLookbehind, nNegLookbehind:
		body := c.compile(n.subs[0], func(m *machine, pos int, k cont) bool { return k(pos) })
		neg := n.kind == nNegLookbehind
		minw, maxw := width(n.subs[0])
		return func(m *machine, pos int, k cont) bool {
			saved := append([]int(nil), m.caps...)
			ok := false
			lo := 0
			if maxw >= 0 {
				lo = pos - maxw
				if lo < 0 {
					lo = 0
				}
			}
			for s := pos - minw; s >= lo; s-- {
				if body(m, s, func(p int) bool { return p == pos }) {
					ok = true
					break
				}
			}
			if neg {
				copy(m.caps, saved)
				if ok {
					return false
				}
				return next(m, pos, k)
			}
			if !ok {
				copy(m.caps, saved)
				return false
			}
			if next(m, pos, k) {
				return true
			}
			copy(m.caps, saved)
			return false
		}
	case nAtomic:
		body := c.compile(n.subs[0], func(m *machine, pos int, k cont) bool { return k(pos) })
		return func(m *machine, pos int, k cont) bool {
			saved := append([]int(nil), m.caps...)
			end := -1
			if !body(m, pos, func(p int) bool { end = p; return true }) {
				copy(m.caps, saved)
				return false
			}
			if next(m, end, k) {
				return true
			}
			copy(m.caps, saved)
			return false
		}
	case nBackref:
		idx := n.group
		fold := n.fold
		return func(m *machine, pos int, k cont) bool {
			s, e := m.caps[2*idx], m.caps[2*idx+1]
