				return false
			}
			l := e - s
			if pos+l > len(m.text) {
				return false
			}
			for i := 0; i < l; i++ {
				a, b := m.text[s+i], m.text[pos+i]
				if a != b {
					if !fold || lower(a) != lower(b) {
