					}
				}
			}
			return next(m, pos+l, k)
		}
	case nCond:
		yes := c.compile(n.subs[0], next)
		no := c.compile(n.subs[1], next)
		if n.condGrp >= 0 {
			g := n.condGrp
			return func(m *machine, pos int, k cont) bool {
				if g < len(m.caps)/2 && m.caps[2*g] >= 0 {
					return yes(m, pos, k)
				}
				return no(m, pos, k)
			}
		}
		cond := c.compile(n.condExpr, func(m *machine, pos int, k cont) bool { return k(pos) })
		return func(m *machine, pos int, k cont) bool {
			if cond(m, pos, func(p int) bool { return true }) {
				return yes(m, pos, k)
			}
			return no(m, pos, k)
		}
	case nRepeat:
		return c.compileRepeat(n, next)
	}
	panic("unknown node")
}

func (c *compiler) compileRepeat(n *node, next mfn) mfn {
	sub := n.subs[0]
	min, max := n.min, n.max
	if isSingle(sub) {
		test := singleTest(sub)
		if !n.lazy {
			return func(m *machine, pos int, k cont) bool {
				t := m.text
				i := pos
				lim := len(t)
				if max >= 0 && pos+max < lim {
					lim = pos + max
				}
				for i < lim && test(t[i]) {
					i++
				}
				if i-pos < min {
					return false
				}
				for ; i >= pos+min; i-- {
					if next(m, i, k) {
						return true
					}
				}
				return false
			}
		}
		return func(m *machine, pos int, k cont) bool {
			t := m.text
			i := pos
			for j := 0; j < min; j++ {
				if i >= len(t) || !test(t[i]) {
					return false
				}
				i++
			}
			count := min
			for {
				if next(m, i, k) {
					return true
				}
				if max >= 0 && count >= max {
					return false
				}
				if i >= len(t) || !test(t[i]) {
					return false
				}
				i++
				count++
			}
		}
	}
	// general case
	var body mfn = c.compile(sub, func(m *machine, pos int, k cont) bool { return k(pos) })
	lazy := n.lazy
	var try func(m *machine, pos int, count int, k cont) bool
	try = func(m *machine, pos int, count int, k cont) bool {
		if lazy {
			if count >= min {
				if next(m, pos, k) {
					return true
				}
			}
			if max >= 0 && count >= max {
				return false
			}
			return body(m, pos, func(p int) bool {
				if p == pos && count >= min {
					return false
				}
				return try(m, p, count+1, k)
			})
		}
		if max < 0 || count < max {
			if body(m, pos, func(p int) bool {
				if p == pos {
					// empty iteration: stop looping
					if count+1 >= min {
						return next(m, p, k)
					}
					return try(m, p, count+1, k)
				}
				return try(m, p, count+1, k)
			}) {
				return true
			}
		}
		if count >= min {
			return next(m, pos, k)
		}
		return false
	}
	return func(m *machine, pos int, k cont) bool {
		return try(m, pos, 0, k)
	}
}

// width returns min and max width (-1 for unbounded) of a node.
func width(n *node) (int, int) {
	switch n.kind {
	case nChar, nSet, nAny:
		return 1, 1
	case nEmpty, nBol, nEol, nBeginText, nEndTextZ, nEndText, nStartPos, nWordB, nNonWordB,
		nLookahead, nNegLookahead, nLookbehind, nNegLookbehind:
		return 0, 0
	case nConcat:
		mn, mx := 0, 0
		for _, s := range n.subs {
			a, b := width(s)
			mn += a
			if mx >= 0 {
				if b < 0 {
					mx = -1
				} else {
					mx += b
				}
			}
		}
		return mn, mx
	case nAlt:
		mn, mx := -1, 0
		for _, s := range n.subs {
			a, b := width(s)
			if mn < 0 || a < mn {
				mn = a
			}
			if mx >= 0 {
				if b < 0 {
					mx = -1
				} else if b > mx {
					mx = b
				}
			}
		}
		if mn < 0 {
			mn = 0
		}
		return mn, mx
	case nGroup, nNonCap, nAtomic:
		return width(n.subs[0])
	case nRepeat:
		a, b := width(n.subs[0])
		mn := a * n.min
		mx := -1
		if n.max >= 0 && b >= 0 {
			mx = b * n.max
		}
		return mn, mx
	case nCond:
		a1, b1 := width(n.subs[0])
		a2, b2 := width(n.subs[1])
		mn := a1
		if a2 < mn {
			mn = a2
		}
		mx := b1
		if b1 < 0 || b2 < 0 {
			mx = -1
		} else if b2 > mx {
			mx = b2
		}
		return mn, mx
	}
	return 0, -1
}
