cat > first.go <<'EOF'
package regex

type firstInfo struct {
	nullable bool
	ascii    [4]uint32
	nonASCII bool
}

func (f *firstInfo) accept(r rune) bool {
	if r < 128 {
		return f.ascii[r>>5]&(1<<(uint(r)&31)) != 0
	}
	return f.nonASCII
}

func (f *firstInfo) union(o firstInfo) {
	for i := range f.ascii {
		f.ascii[i] |= o.ascii[i]
	}
	f.nonASCII = f.nonASCII || o.nonASCII
}

func allFirst() firstInfo {
	f := firstInfo{nonASCII: true}
	for i := range f.ascii {
		f.ascii[i] = 0xffffffff
	}
	return f
}

// firstOf computes the set of runes that may start a match, and nullability.
func firstOf(n *node) firstInfo {
	switch n.kind {
	case nChar, nSet, nAny:
		f := firstInfo{}
		test := singleTest(n)
		for r := rune(0); r < 128; r++ {
			if test(r) {
				f.ascii[r>>5] |= 1 << (uint(r) & 31)
			}
		}
		switch n.kind {
		case nChar:
			f.nonASCII = n.ch >= 128 || n.fold
		default:
			f.nonASCII = true
		}
		return f
	case nEmpty, nBol, nEol, nBeginText, nEndTextZ, nEndText, nStartPos, nWordB, nNonWordB,
		nLookahead, nNegLookahead, nLookbehind, nNegLookbehind:
		return firstInfo{nullable: true}
	case nBackref, nCond:
		f := allFirst()
		f.nullable = true
		return f
	case nConcat:
		f := firstInfo{}
		for _, s := range n.subs {
			sf := firstOf(s)
			f.union(sf)
			if !sf.nullable {
				return f
			}
		}
		f.nullable = true
		return f
	case nAlt:
		f := firstInfo{}
		for _, s := range n.subs {
			sf := firstOf(s)
			f.union(sf)
			if sf.nullable {
				f.nullable = true
			}
		}
		return f
	case nGroup, nNonCap, nAtomic:
		return firstOf(n.subs[0])
	case nRepeat:
		f := firstOf(n.subs[0])
		if n.min == 0 {
			f.nullable = true
		}
		return f
	}
	f := allFirst()
	f.nullable = true
	return f
}
