package chroma

import "fmt"

// Emit implements Emitter for TokenType.
func (t TokenType) Emit(groups []string, _ *LexerState) Iterator {
	if t == Ignore {
		return Literator()
	}
	return Literator(Token{Type: t, Value: groups[0]})
}

// EmitterFunc wraps a function.
type EmitterFunc func(groups []string, state *LexerState) Iterator

func (e EmitterFunc) Emit(groups []string, state *LexerState) Iterator { return e(groups, state) }

type byGroupsEmitter struct{ Emitters []Emitter }

// ByGroups emits a token for each matching group.
func ByGroups(emitters ...Emitter) Emitter { return &byGroupsEmitter{emitters} }

func (b *byGroupsEmitter) Emit(groups []string, state *LexerState) Iterator {
	var iterators []Iterator
	if len(b.Emitters) != len(groups)-1 {
		iterators = append(iterators, Error.Emit(groups, state))
	} else {
