type MutatorFunc func(state *LexerState) error

func (m MutatorFunc) Mutate(state *LexerState) error { return m(state) }

type multiMutator struct{ Mutators []Mutator }

func Mutators(modifiers ...Mutator) Mutator { return &multiMutator{modifiers} }

func (m *multiMutator) Mutate(state *LexerState) error {
	for _, mod := range m.Mutators {
