			return err
		}
	}
	return nil
}

type pushMutator struct{ States []string }

// Push states onto the stack, or the current state if none given.
func Push(states ...string) Mutator { return &pushMutator{states} }

func (p *pushMutator) Mutate(s *LexerState) error {
	if len(p.States) == 0 {
		s.Stack = append(s.Stack, s.State)
	} else {
		for _, state := range p.States {
			if state == "#pop" {
				s.Stack = s.Stack[:len(s.Stack)-1]
			} else {
				s.Stack = append(s.Stack, state)
			}
		}
	}
	return nil
}

type popMutator struct{ Depth int }

func Pop(n int) Mutator { return &popMutator{n} }

func (p *popMutator) Mutate(state *LexerState) error {
	if len(state.Stack) == 0 {
		return fmt.Errorf("nothing to pop")
	}
	state.Stack = state.Stack[:len(state.Stack)-p.Depth]
	return nil
}

type combinedMutator struct{ States []string }

func Combined(states ...string) Mutator { return &combinedMutator{states} }

func (c *combinedMutator) Mutate(s *LexerState) error {
	name := "__combined_" + strings.Join(c.States, "__")
	if _, ok := s.Rules[name]; !ok {
		var rules []*CompiledRule
		for _, state := range c.States {
			rs, ok := s.Rules[state]
			if !ok {
				return fmt.Errorf("invalid combine state %q", state)
			}
			rules = append(rules, rs...)
		}
		s.Rules[name] = rules
	}
	s.Stack = append(s.Stack, name)
	return nil
}

// Default returns a rule that always matches with the given mutators.
func Default(mutators ...Mutator) Rule {
	return Rule{Mutator: Mutators(mutators...)}
