package chroma

import (
	"fmt"
	"strings"
	"unicode/utf8"

	"hl/internal/regex"
)

// Config for a lexer.
type Config struct {
	Name            string
	Aliases         []string
	Filenames       []string
	AliasFilenames  []string
	MimeTypes       []string
	CaseInsensitive bool
	DotAll          bool
	NotMultiline    bool
	EnsureNL        bool
	Priority        float32
	Analyse         *AnalyseConfig
}

type AnalyseConfig struct {
	Regexes []RegexConfig
	First   bool
	Single  bool
}

type RegexConfig struct {
	Pattern string
	Score   float32
}

// TokeniseOptions controls tokenisation.
type TokeniseOptions struct {
	State    string
	Nested   bool
	EnsureLF bool
}

// Lexer interface.
type Lexer interface {
	Config() *Config
	Tokenise(options *TokeniseOptions, text string) (Iterator, error)
	SetRegistry(r *LexerRegistry) Lexer
	SetAnalyser(analyser func(text string) float32) Lexer
	AnalyseText(text string) float32
}

// Emitter emits tokens for matched groups.
type Emitter interface {
	Emit(groups []string, state *LexerState) Iterator
}

// Mutator mutates lexer state.
type Mutator interface {
	Mutate(state *LexerState) error
}

// Rule is a single lexer rule.
type Rule struct {
	Pattern string
	Type    Emitter
	Mutator Mutator
}

type includeMutator struct{ state string }

func (includeMutator) Mutate(*LexerState) error { return nil }

// Include another state's rules.
func Include(state string) Rule { return Rule{Mutator: includeMutator{state}} }

type CompiledRule struct {
	Rule
	Regexp *regex.Regexp
	flags  int
}

type CompiledRules map[string][]*CompiledRule

// Rules is a map of state to rules.
type Rules map[string][]Rule

// RegexLexer is the standard regex-based lexer.
type RegexLexer struct {
	config   *Config
	rules    Rules
	fetch    func() Rules
	compiled CompiledRules
	analyser func(text string) float32
	registry *LexerRegistry
	compileErr error
	compiledOK bool
	// Trace output
	trace bool
}

// NewLexer creates a regex lexer.
func NewLexer(config *Config, rulesFunc func() Rules) (*RegexLexer, error) {
	if config == nil {
		config = &Config{}
	}
	return &RegexLexer{config: config, fetch: rulesFunc}, nil
}

func MustNewLexer(config *Config, rulesFunc func() Rules) *RegexLexer {
	l, _ := NewLexer(config, rulesFunc)
	return l
}

func (r *RegexLexer) Config() *Config { return r.config }
func (r *RegexLexer) SetRegistry(reg *LexerRegistry) Lexer {
	r.registry = reg
	return r
}
func (r *RegexLexer) SetAnalyser(a func(text string) float32) Lexer {
	r.analyser = a
	return r
}
func (r *RegexLexer) AnalyseText(text string) float32 {
	if r.analyser != nil {
		return r.analyser(text)
	}
	return 0
}
func (r *RegexLexer) SetTrace(t bool) *RegexLexer { r.trace = t; return r }

func (r *RegexLexer) Rules() (Rules, error) {
	if err := r.maybeCompile(); err != nil {
		return nil, err
	}
	return r.rules, nil
}

func (r *RegexLexer) maybeCompile() error {
	if r.compiledOK {
		return r.compileErr
	}
	r.compiledOK = true
	if r.rules == nil {
		r.rules = r.fetch()
	}
	r.compileErr = r.compile()
	return r.compileErr
}

func (r *RegexLexer) compile() error {
	rules := map[string][]*CompiledRule{}
	for state, rs := range r.rules {
		for _, rule := range rs {
			cr := &CompiledRule{Rule: rule}
			rules[state] = append(rules[state], cr)
		}
	}
	// Expand includes.
	if err := expandIncludes(rules); err != nil {
		return err
	}
	// Combined states are compiled lazily
	flags := 0
	if !r.config.NotMultiline {
		flags |= regex.FlagMultiline
	}
	if r.config.CaseInsensitive {
		flags |= regex.FlagIgnoreCase
	}
	if r.config.DotAll {
		flags |= regex.FlagSingleline
	}
	for state, rs := range rules {
		for i, rule := range rs {
			if rule.Regexp == nil {
				re, err := regex.Compile(rule.Pattern, flags)
				if err != nil {
					if e, ok := err.(*regex.Error); ok {
						e.Pattern = `\G(?` + flagString(flags) + `)(?:` + rule.Pattern + `)`
					}
					return fmt.Errorf("failed to compile rule %s.%d: %s", state, i, err)
				}
				rule.Regexp = re
				rule.flags = flags
			}
		}
	}
	r.compiled = rules
	return nil
}

func flagString(flags int) string {
	s := ""
	if flags&regex.FlagIgnoreCase != 0 {
		s += "i"
	}
	if flags&regex.FlagMultiline != 0 {
		s += "m"
	}
	if flags&regex.FlagSingleline != 0 {
		s += "s"
	}
	return s
}

func expandIncludes(rules map[string][]*CompiledRule) error {
	for {
		changed := false
		for state, rs := range rules {
			for i := 0; i < len(rs); i++ {
				rule := rs[i]
				if inc, ok := rule.Mutator.(includeMutator); ok {
					other, ok := rules[inc.state]
					if !ok {
						return fmt.Errorf("include(%q) is not a valid state", inc.state)
					}
					nr := append([]*CompiledRule{}, rs[:i]...)
					nr = append(nr, other...)
					nr = append(nr, rs[i+1:]...)
					rs = nr
					rules[state] = rs
					changed = true
					i--
				}
			}
		}
		if !changed {
			return nil
		}
	}
}

// Tokenise text.
func (r *RegexLexer) Tokenise(options *TokeniseOptions, text string) (Iterator, error) {
	if err := r.maybeCompile(); err != nil {
		return nil, err
	}
	if options == nil {
		options = &TokeniseOptions{State: "root"}
	}
	if options.State == "" {
		options.State = "root"
	}
	if options.EnsureLF {
		text = strings.ReplaceAll(text, "\r\n", "\n")
		text = strings.ReplaceAll(text, "\r", "\n")
	}
	newlineAdded := false
	if !options.Nested && r.config.EnsureNL && !strings.HasSuffix(text, "\n") {
		text += "\n"
		newlineAdded = true
	}
	state := &LexerState{
		Registry:     r.registry,
		Lexer:        r,
		options:      options,
		Text:         []rune(text),
		Stack:        []string{options.State},
		Rules:        r.compiled,
		MutatorContext: map[interface{}]interface{}{},
		newlineAdded: newlineAdded,
	}
	return state.Iterator, nil
}

// LexerState is the state of the lexer during tokenisation.
type LexerState struct {
	Registry       *LexerRegistry
	Lexer          *RegexLexer
	Rules          CompiledRules
	Text           []rune
	Pos            int
	Rule           int
	Stack          []string
	State          string
	Groups         []string
	NamedGroups    map[string]string
	MutatorContext map[interface{}]interface{}
	iteratorStack  []Iterator
	options        *TokeniseOptions
	newlineAdded   bool
}

func (l *LexerState) Set(key interface{}, value interface{}) { l.MutatorContext[key] = value }
func (l *LexerState) Get(key interface{}) interface{}        { return l.MutatorContext[key] }

func (l *LexerState) Iterator() Token {
	end := len(l.Text)
	if l.newlineAdded {
		end--
	}
	for l.Pos < end && len(l.Stack) > 0 {
		for len(l.iteratorStack) > 0 {
			n := len(l.iteratorStack) - 1
			t := l.iteratorStack[n]()
			if t == EOF {
				l.iteratorStack = l.iteratorStack[:n]
				continue
			}
			return t
		}
		l.State = l.Stack[len(l.Stack)-1]
		selectedRule, ok := l.Rules[l.State]
		if !ok {
			// combined state?
			if strings.HasPrefix(l.State, "__combined_") {
				selectedRule = l.makeCombined(l.State)
			}
			if selectedRule == nil {
				panic(fmt.Sprintf("unknown state %q", l.State))
			}
		}
		ruleIndex, rule, groups := matchRules(l.Text, l.Pos, selectedRule)
		if groups == nil {
			if l.Text[l.Pos] == '\n' && l.State != l.options.State {
				l.Stack = []string{l.options.State}
				continue
			}
			l.Pos++
			return Token{Error, string(l.Text[l.Pos-1 : l.Pos])}
		}
		l.Rule = ruleIndex
		l.Groups = groups
		l.Pos += utf8.RuneCountInString(groups[0])
		if rule.Mutator != nil {
			if err := rule.Mutator.Mutate(l); err != nil {
				panic(err)
			}
		}
		if rule.Type != nil {
			l.iteratorStack = append(l.iteratorStack, rule.Type.Emit(l.Groups, l))
		}
	}
	for len(l.iteratorStack) > 0 {
		n := len(l.iteratorStack) - 1
		t := l.iteratorStack[n]()
		if t == EOF {
			l.iteratorStack = l.iteratorStack[:n]
			continue
		}
		return t
	}
	if l.Pos != len(l.Text) && len(l.Stack) == 0 {
		value := string(l.Text[l.Pos:])
		l.Pos = len(l.Text)
		return Token{Type: Error, Value: value}
	}
	return EOF
}

func (l *LexerState) makeCombined(name string) []*CompiledRule {
	parts := strings.Split(strings.TrimPrefix(name, "__combined_"), "__")
	var out []*CompiledRule
	for _, p := range parts {
		rs, ok := l.Rules[p]
		if !ok {
			return nil
		}
		out = append(out, rs...)
	}
	l.Rules[name] = out
	return out
}

func matchRules(text []rune, pos int, rules []*CompiledRule) (int, *CompiledRule, []string) {
	for i, rule := range rules {
		caps := rule.Regexp.MatchAt(text, pos)
		if caps != nil {
			groups := make([]string, len(caps)/2)
			for g := 0; g < len(groups); g++ {
				s, e := caps[2*g], caps[2*g+1]
				if s >= 0 && e >= s {
					groups[g] = string(text[s:e])
				}
			}
			return i, rule, groups
		}
	}
	return 0, nil, nil
}
