package chroma

import (
	"bytes"
	"fmt"
	"io/fs"
	"strconv"
	"strings"

	"hl/internal/regex"
)

// NewXMLLexer loads a lexer from an XML file in a filesystem.
func NewXMLLexer(from fs.FS, path string) (*RegexLexer, error) {
	data, err := fs.ReadFile(from, path)
	if err != nil {
		return nil, err
	}
	return NewXMLLexerFromBytes(data, path)
}

func NewXMLLexerFromBytes(data []byte, path string) (*RegexLexer, error) {
	root, err := ParseXML(bytes.NewReader(data))
	if err != nil {
		return nil, fmt.Errorf("%s: %w", path, err)
	}
	cfgNode := root.Child("config")
	config := &Config{}
	if cfgNode != nil {
		for _, c := range cfgNode.Children {
			v := c.TrimText()
			switch c.Name {
			case "name":
				config.Name = v
			case "alias":
				config.Aliases = append(config.Aliases, v)
			case "filename":
				config.Filenames = append(config.Filenames, v)
			case "alias_filename":
				config.AliasFilenames = append(config.AliasFilenames, v)
			case "mime_type":
				config.MimeTypes = append(config.MimeTypes, v)
			case "case_insensitive":
				config.CaseInsensitive = v == "true"
			case "dot_all":
				config.DotAll = v == "true"
			case "not_multiline":
				config.NotMultiline = v == "true"
			case "ensure_nl":
				config.EnsureNL = v == "true"
			case "priority":
				f, _ := strconv.ParseFloat(v, 32)
				config.Priority = float32(f)
			case "analyse":
				ac := &AnalyseConfig{}
				if a, ok := c.Attr("first"); ok {
					ac.First = a == "true"
				}
				if a, ok := c.Attr("single"); ok {
					ac.Single = a == "true"
				}
				for _, r := range c.ChildrenNamed("regex") {
					p, _ := r.Attr("pattern")
					s, _ := r.Attr("score")
					f, _ := strconv.ParseFloat(s, 32)
					ac.Regexes = append(ac.Regexes, RegexConfig{Pattern: p, Score: float32(f)})
				}
				config.Analyse = ac
			}
		}
	}
	rulesNode := root.Child("rules")
	rules := Rules{}
	var buildErr error
	if rulesNode != nil {
		for _, st := range rulesNode.ChildrenNamed("state") {
			name, _ := st.Attr("name")
			rules[name] = []Rule{}
			for _, rn := range st.ChildrenNamed("rule") {
				rule, err := parseXMLRule(rn)
				if err != nil {
					if buildErr == nil {
						buildErr = fmt.Errorf("%s: failed to compile rules: %s: %w", config.Name, path, err)
					}
					continue
				}
				rules[name] = append(rules[name], rule)
			}
		}
	}
	if buildErr != nil {
		return nil, buildErr
	}
	// validate bygroups counts
	for state, rs := range rules {
		for _, r := range rs {
			if bg, ok := r.Type.(*byGroupsEmitter); ok && r.Pattern != "" {
				re, err := regex.Compile(r.Pattern, 0)
				if err == nil && re.NumGroups() != len(bg.Emitters) {
					return nil, fmt.Errorf("%s: %s: %s: number of groups %d does not match number of emitters %d", config.Name, state, r.Pattern, re.NumGroups(), len(bg.Emitters))
				}
			}
		}
	}
	lexer := MustNewLexer(config, func() Rules { return rules })
	if config.Analyse != nil {
		ac := config.Analyse
		var res []*regex.Regexp
		var scores []float32
		for _, rc := range ac.Regexes {
			re, err := regex.Compile(rc.Pattern, 0)
			if err != nil {
				return nil, err
			}
			res = append(res, re)
			scores = append(scores, rc.Score)
		}
		lexer.SetAnalyser(func(text string) float32 {
			var score float32
			runes := []rune(text)
			for i, re := range res {
				if re.FindFrom(runes, 0) != nil {
					if ac.First {
						return scores[i]
					}
					score += scores[i]
				}
				_ = ac.Single
			}
			if score > 1 {
				score = 1
			}
			return score
		})
	}
	return lexer, nil
}

func parseXMLRule(n *XMLNode) (Rule, error) {
	rule := Rule{}
	rule.Pattern, _ = n.Attr("pattern")
	var mutators []Mutator
	for _, c := range n.Children {
		switch c.Name {
		case "include":
			s, _ := c.Attr("state")
			return Include(s), nil
		case "push", "pop", "combined", "mutators":
			m, err := parseXMLMutator(c)
			if err != nil {
				return rule, err
			}
			mutators = append(mutators, m)
		default:
			e, err := parseXMLEmitter(c)
			if err != nil {
				return rule, err
			}
			rule.Type = e
		}
	}
	if len(mutators) == 1 {
		rule.Mutator = mutators[0]
	} else if len(mutators) > 1 {
		rule.Mutator = Mutators(mutators...)
	}
	return rule, nil
}

func parseXMLMutator(c *XMLNode) (Mutator, error) {
	switch c.Name {
	case "push":
		states := c.AttrAll("state")
		var out []string
		for _, s := range states {
			out = append(out, s)
		}
		return Push(out...), nil
	case "pop":
		d, _ := c.Attr("depth")
		n, err := strconv.Atoi(d)
		if err != nil {
			n = 1
		}
		return Pop(n), nil
	case "combined":
		s, _ := c.Attr("states")
		var states []string
		if s != "" {
			states = strings.Fields(s)
		}
		for _, st := range c.ChildrenNamed("state") {
			states = append(states, st.TrimText())
		}
		return Combined(states...), nil
	case "mutators":
		var ms []Mutator
		for _, cc := range c.Children {
			m, err := parseXMLMutator(cc)
			if err != nil {
				return nil, err
			}
			ms = append(ms, m)
		}
		return Mutators(ms...), nil
	}
	return nil, fmt.Errorf("unknown mutator %q", c.Name)
}

func parseXMLEmitter(c *XMLNode) (Emitter, error) {
	switch c.Name {
	case "token":
		t, _ := c.Attr("type")
		tt, err := TokenTypeString(t)
		if err != nil {
			return nil, err
		}
		return tt, nil
	case "none":
		return nil, nil
	case "bygroups":
		var ems []Emitter
		for _, cc := range c.Children {
			e, err := parseXMLEmitter(cc)
			if err != nil {
				return nil, err
			}
			ems = append(ems, e)
		}
		return ByGroups(ems...), nil
	case "using":
		l, _ := c.Attr("lexer")
		return Using(l), nil
	case "usingself":
		s, _ := c.Attr("state")
		return UsingSelf(s), nil
	case "usingbygroup":
		a, _ := c.Attr("sublexer_name_group")
		b, _ := c.Attr("code_group")
		ai, _ := strconv.Atoi(a)
		bi, _ := strconv.Atoi(b)
		var ems []Emitter
		emNode := c.Child("emitters")
		if emNode == nil {
			emNode = c
		}
		for _, cc := range emNode.Children {
			e, err := parseXMLEmitter(cc)
			if err != nil {
				return nil, err
			}
			ems = append(ems, e)
		}
		return UsingByGroup(ai, bi, ems...), nil
	}
	return nil, fmt.Errorf("unknown emitter %q", c.Name)
}
