		}
	}
	if buildErr != nil {
		return nil, buildErr
	}
	// validate bygroups counts
	for state, rs := range rules {
		for _, r := range rs {
			if bg, ok := r.Type.(*byGroupsEmitter); ok && r.Pattern != "" {
				re, err := regex.Compile(r.Pattern, 0)
				if err == nil && re.NumGroups() != len(bg.Emitters) {
					return nil, fmt.Errorf("%s: %s: %s: number of groups %d does not match number of emitters %d", config.Name, state, r.Pattern, re.NumGroups(), len(bg.Emitters))
				}
			}
		}
	}
	lexer := MustNewLexer(config, func() Rules { return rules })
	if config.Analyse != nil {
		ac := config.Analyse
		var res []*regex.Regexp
		var scores []float32
		for _, rc := range ac.Regexes {
			re, err := regex.Compile(rc.Pattern, 0)
			if err != nil {
				return nil, err
			}
			res = append(res, re)
			scores = append(scores, rc.Score)
		}
		lexer.SetAnalyser(func(text string) float32 {
			var score float32
			runes := []rune(text)
			for i, re := range res {
				if re.FindFrom(runes, 0) != nil {
					if ac.First {
						return scores[i]
					}
					score += scores[i]
				}
				_ = ac.Single
			}
			if score > 1 {
				score = 1
			}
			return score
		})
	}
	return lexer, nil
}

func parseXMLRule(n *XMLNode) (Rule, error) {
	rule := Rule{}
	rule.Pattern, _ = n.Attr("pattern")
	var mutators []Mutator
	for _, c := range n.Children {
		switch c.Name {
		case "include":
			s, _ := c.Attr("state")
			return Include(s), nil
		case "push", "pop", "combined", "mutators":
			m, err := parseXMLMutator(c)
			if err != nil {
				return rule, err
			}
			mutators = append(mutators, m)
		default:
			e, err := parseXMLEmitter(c)
			if err != nil {
				return rule, err
			}
			rule.Type = e
		}
	}
	if len(mutators) == 1 {
		rule.Mutator = mutators[0]
	} else if len(mutators) > 1 {
		rule.Mutator = Mutators(mutators...)
	}
	return rule, nil
}

func parseXMLMutator(c *XMLNode) (Mutator, error) {
	switch c.Name {
	case "push":
		states := c.AttrAll("state")
		var out []string
		for _, s := range states {
			out = append(out, s)
		}
		return Push(out...), nil
	case "pop":
		d, _ := c.Attr("depth")
		n, err := strconv.Atoi(d)
		if err != nil {
			n = 1
		}
		return Pop(n), nil
	case "combined":
		s, _ := c.Attr("states")
		var states []string
		if s != "" {
			states = strings.Fields(s)
		}
		for _, st := range c.ChildrenNamed("state") {
			states = append(states, st.TrimText())
		}
		return Combined(states...), nil
	case "mutators":
		var ms []Mutator
		for _, cc := range c.Children {
			m, err := parseXMLMutator(cc)
			if err != nil {
				return nil, err
			}
			ms = append(ms, m)
		}
		return Mutators(ms...), nil
	}
	return nil, fmt.Errorf("unknown mutator %q", c.Name)
}

func parseXMLEmitter(c *XMLNode) (Emitter, error) {
	switch c.Name {
	case "token":
		t, _ := c.Attr("type")
		tt, err := TokenTypeString(t)
		if err != nil {
			return nil, err
		}
		return tt, nil
	case "none":
		return nil, nil
	case "bygroups":
		var ems []Emitter
		for _, cc := range c.Children {
			e, err := parseXMLEmitter(cc)
			if err != nil {
				return nil, err
			}
			ems = append(ems, e)
		}
		return ByGroups(ems...), nil
	case "using":
		l, _ := c.Attr("lexer")
		return Using(l), nil
	case "usingself":
		s, _ := c.Attr("state")
		return UsingSelf(s), nil
	case "usingbygroup":
		a, _ := c.Attr("sublexer_name_group")
		b, _ := c.Attr("code_group")
		ai, _ := strconv.Atoi(a)
		bi, _ := strconv.Atoi(b)
		var ems []Emitter
		emNode := c.Child("emitters")
		if emNode == nil {
			emNode = c
		}
		for _, cc := range emNode.Children {
			e, err := parseXMLEmitter(cc)
			if err != nil {
				return nil, err
			}
			ems = append(ems, e)
		}
		return UsingByGroup(ai, bi, ems...), nil
	}
	return nil, fmt.Errorf("unknown emitter %q", c.Name)
}
