import (
	"fmt"
	"io"
	"math"
	"strings"

	"hl/chroma"
)

type ttyTable struct {
	keys       []chroma.Colour
	foreground map[chroma.Colour]string
	background map[chroma.Colour]string
}

var c = chroma.ParseColour

func mkTable(cols []string, fg []string, bg []string) *ttyTable {
	t := &ttyTable{foreground: map[chroma.Colour]string{}, background: map[chroma.Colour]string{}}
	for i, col := range cols {
		k := c(col)
		if _, ok := t.foreground[k]; !ok {
			t.keys = append(t.keys, k)
		}
		t.foreground[k] = fg[i]
		t.background[k] = bg[i]
	}
	return t
}

var basic16 = []string{"#000000", "#7f0000", "#007f00", "#7f7fe0", "#00007f", "#7f007f", "#007f7f", "#e5e5e5",
	"#555555", "#ff0000", "#00ff00", "#ffff00", "#0000ff", "#ff00ff", "#00ffff", "#ffffff"}

var ttyTables = map[int]*ttyTable{}

func init() {
	var fg8, bg8, fg16, bg16 []string
	for i := 0; i < 8; i++ {
		fg8 = append(fg8, fmt.Sprintf("\033[%dm", 30+i))
		bg8 = append(bg8, fmt.Sprintf("\033[%dm", 40+i))
		fg16 = append(fg16, fmt.Sprintf("\033[%dm", 30+i))
		bg16 = append(bg16, fmt.Sprintf("\033[%dm", 40+i))
	}
	for i := 0; i < 8; i++ {
		fg8 = append(fg8, fmt.Sprintf("\033[1m\033[%dm", 30+i))
		bg8 = append(bg8, fmt.Sprintf("\033[1m\033[%dm", 40+i))
		fg16 = append(fg16, fmt.Sprintf("\033[%dm", 90+i))
		bg16 = append(bg16, fmt.Sprintf("\033[%dm", 100+i))
	}
	ttyTables[8] = mkTable(basic16, fg8, bg8)
	ttyTables[16] = mkTable(basic16, fg16, bg16)
	var cols, fg, bg []string
	sys := []string{"#000000", "#800000", "#008000", "#808000", "#000080", "#800080", "#008080", "#c0c0c0",
		"#808080", "#ff0000", "#00ff00", "#ffff00", "#0000ff", "#ff00ff", "#00ffff", "#ffffff"}
	add := func(i int, col string) {
		cols = append(cols, col)
		fg = append(fg, fmt.Sprintf("\033[38;5;%dm", i))
		bg = append(bg, fmt.Sprintf("\033[48;5;%dm", i))
	}
	for i, s := range sys {
		add(i, s)
	}
	lv := []int{0, 95, 135, 175, 215, 255}
	i := 16
	for _, r := range lv {
		for _, g := range lv {
			for _, b := range lv {
				add(i, fmt.Sprintf("#%02x%02x%02x", r, g, b))
				i++
			}
		}
	}
	for k := 0; k < 24; k++ {
		v := 8 + 10*k
		add(232+k, fmt.Sprintf("#%02x%02x%02x", v, v, v))
	}
	ttyTables[256] = mkTable(cols, fg, bg)
}

func distance(a, b chroma.Colour) float64 {
	ar, ag, ab := int64(a.Red()), int64(a.Green()), int64(a.Blue())
	br, bg, bb := int64(b.Red()), int64(b.Green()), int64(b.Blue())
	rmean := (ar + br) / 2
	r := ar - br
	g := ag - bg
	bl := ab - bb
	return math.Sqrt(float64((((512 + rmean) * r * r) >> 8) + 4*g*g + (((767 - rmean) * bl * bl) >> 8)))
}

func findClosest(table *ttyTable, seeking chroma.Colour) chroma.Colour {
	closestColour := chroma.Colour(0)
	closest := math.MaxFloat64
	for _, colour := range table.keys {
		d := distance(colour, seeking)
		if d < closest {
			closest = d
			closestColour = colour
		}
	}
	return closestColour
}

func entryToEscapeSequence(table *ttyTable, entry chroma.StyleEntry) string {
	out := ""
	if entry.Bold == chroma.Yes {
		out += "\033[1m"
	}
	if entry.Underline == chroma.Yes {
		out += "\033[4m"
	}
	if entry.Italic == chroma.Yes {
		out += "\033[3m"
	}
	if entry.Colour.IsSet() {
		out += table.foreground[findClosest(table, entry.Colour)]
	}
	if entry.Background.IsSet() {
		out += table.background[findClosest(table, entry.Background)]
	}
	return out
}

func clearBackground(style *chroma.Style) *chroma.Style {
	s := style.Clone()
	bg := style.Get(chroma.Background)
	bg.Background = 0
	bg.NoInherit = true
	s.SetEntry(chroma.Background, bg)
	return s
}

func styleToEscapeSequence(table *ttyTable, style *chroma.Style) map[chroma.TokenType]string {
	style = clearBackground(style)
	out := map[chroma.TokenType]string{}
	for _, ttype := range style.Types() {
		entry := style.Get(ttype)
		out[ttype] = entryToEscapeSequence(table, entry)
	}
	return out
}

func writeToken(w io.Writer, formatting string, text string) {
	if formatting == "" {
		fmt.Fprint(w, text)
		return
	}
	newlineIndex := strings.Index(text, "\n")
	if newlineIndex == -1 {
		fmt.Fprint(w, formatting+text+"\033[0m")
		return
	}
	for newlineIndex != -1 {
		fmt.Fprint(w, formatting+text[:newlineIndex]+"\033[0m\n")
		text = text[newlineIndex+1:]
		newlineIndex = strings.Index(text, "\n")
	}
	if len(text) > 0 {
		fmt.Fprint(w, formatting+text+"\033[0m")
	}
}

// IndexedTTY formats with an indexed colour table.
func IndexedTTY(colours int) Formatter {
	table := ttyTables[colours]
	return FormatterFunc(func(w io.Writer, style *chroma.Style, it chroma.Iterator) error {
		theme := styleToEscapeSequence(table, style)
		for token := it(); token != chroma.EOF; token = it() {
			clr, ok := theme[token.Type]
			if !ok {
				clr, ok = theme[token.Type.SubCategory()]
				if !ok {
					clr, ok = theme[token.Type.Category()]
					if !ok {
						clr, ok = theme[chroma.Text]
						if !ok {
							clr = theme[chroma.Background]
						}
					}
				}
			}
			writeToken(w, clr, token.Value)
		}
		return nil
	})
}

// TrueColourTTY formats with 24-bit colours.
func TrueColourTTY() Formatter {
	return FormatterFunc(func(w io.Writer, style *chroma.Style, it chroma.Iterator) error {
		style = clearBackground(style)
		for token := it(); token != chroma.EOF; token = it() {
			entry := style.Get(token.Type)
			if entry.IsZero() {
				fmt.Fprint(w, token.Value)
				continue
			}
			out := ""
			if entry.Bold == chroma.Yes {
				out += "\033[1m"
			}
			if entry.Underline == chroma.Yes {
				out += "\033[4m"
			}
			if entry.Italic == chroma.Yes {
				out += "\033[3m"
			}
			if entry.Colour.IsSet() {
				out += fmt.Sprintf("\033[38;2;%d;%d;%dm", entry.Colour.Red(), entry.Colour.Green(), entry.Colour.Blue())
			}
			if entry.Background.IsSet() {
				out += fmt.Sprintf("\033[48;2;%d;%d;%dm", entry.Background.Red(), entry.Background.Green(), entry.Background.Blue())
			}
			writeToken(w, out, token.Value)
		}
		return nil
	})
}
