package formatters

import (
	"encoding/json"
	"fmt"
	"io"

	"hl/chroma"
)

// Formatter formats tokens.
type Formatter interface {
	Format(w io.Writer, style *chroma.Style, iterator chroma.Iterator) error
}

type FormatterFunc func(w io.Writer, style *chroma.Style, iterator chroma.Iterator) error

func (f FormatterFunc) Format(w io.Writer, s *chroma.Style, it chroma.Iterator) (err error) {
	return f(w, s, it)
}

var NoOp = FormatterFunc(func(w io.Writer, s *chroma.Style, it chroma.Iterator) error {
	for t := it(); t != chroma.EOF; t = it() {
		if _, err := io.WriteString(w, t.Value); err != nil {
			return err
		}
	}
	return nil
})

var Tokens = FormatterFunc(func(w io.Writer, s *chroma.Style, it chroma.Iterator) error {
	for t := it(); t != chroma.EOF; t = it() {
		if _, err := fmt.Fprintln(w, t.GoString()); err != nil {
			return err
		}
	}
	return nil
})

var JSON = FormatterFunc(func(w io.Writer, s *chroma.Style, it chroma.Iterator) error {
	if _, err := fmt.Fprintln(w, "["); err != nil {
		return err
	}
	i := 0
	for t := it(); t != chroma.EOF; t = it() {
		if i > 0 {
			if _, err := fmt.Fprintln(w, ","); err != nil {
				return err
			}
		}
		i++
		bytes, err := json.Marshal(struct {
			Type  string `json:"type"`
			Value string `json:"value"`
		}{t.Type.String(), t.Value})
		if err != nil {
			return err
		}
		if _, err := fmt.Fprint(w, "  "+string(bytes)); err != nil {
			return err
		}
	}
	fmt.Fprintln(w)
	fmt.Fprintln(w, "]")
	return nil
})

// Names of formatters.
var Names = []string{"html", "json", "noop", "svg", "terminal", "terminal16", "terminal16m", "terminal256", "terminal8", "tokens"}
