package formatters

import (
	"fmt"
	"html"
	"io"
	"sort"
	"strconv"
	"strings"

	"hl/chroma"
)

// HTMLFormatter formats HTML.
type HTMLFormatter struct {
	Standalone            bool
	Prefix                string
	Classes               bool
	AllClasses            bool
	PreventSurroundingPre bool
	TabWidth              int
	LineNumbers           bool
	LineNumbersInTable    bool
	LinkableLineNumbers   bool
	LineNumbersIDPrefix   string
	HighlightRanges       [][2]int
	BaseLineNumber        int
}

func NewHTML() *HTMLFormatter {
	return &HTMLFormatter{TabWidth: 8, BaseLineNumber: 1, LineNumbersIDPrefix: "L"}
}

func (f *HTMLFormatter) Format(w io.Writer, style *chroma.Style, iterator chroma.Iterator) error {
	return f.writeHTML(w, style, iterator.Tokens())
}

func (f *HTMLFormatter) preStart(code bool, attr string) string {
	if f.PreventSurroundingPre {
		return ""
	}
	if code {
		return fmt.Sprintf("<pre%s><code>", attr)
	}
	return fmt.Sprintf("<pre%s>", attr)
}

func (f *HTMLFormatter) preEnd(code bool) string {
	if f.PreventSurroundingPre {
		return ""
	}
	if code {
		return "</code></pre>"
	}
	return "</pre>"
}

func (f *HTMLFormatter) writeHTML(w io.Writer, style *chroma.Style, tokens []chroma.Token) error {
	css := f.styleToCSS(style)
	if f.Standalone {
		fmt.Fprint(w, "<html>\n")
		if f.Classes {
			fmt.Fprint(w, "<style type=\"text/css\">\n")
			if err := f.WriteCSS(w, style); err != nil {
				return err
			}
			fmt.Fprintf(w, "body { %s; }\n", css[chroma.Background])
			fmt.Fprint(w, "</style>")
		}
		fmt.Fprintf(w, "<body%s>\n", f.styleAttr(css, chroma.Background))
	}
	wrapInTable := f.LineNumbers && f.LineNumbersInTable
	lines := chroma.SplitTokensIntoLines(tokens)
	lineDigits := len(strconv.Itoa(f.BaseLineNumber + len(lines) - 1))
	highlightIndex := 0
	if wrapInTable {
		fmt.Fprintf(w, "<div%s>\n", f.styleAttr(css, chroma.PreWrapper))
		fmt.Fprintf(w, "<table%s><tr>", f.styleAttr(css, chroma.LineTable))
		fmt.Fprintf(w, "<td%s>\n", f.styleAttr(css, chroma.LineTableTD))
		fmt.Fprintf(w, "%s", f.preStart(false, f.styleAttr(css, chroma.PreWrapper)))
		for index := range lines {
			line := f.BaseLineNumber + index
			highlight, next := f.shouldHighlight(highlightIndex, line)
			if next {
				highlightIndex++
			}
			if highlight {
				fmt.Fprintf(w, "<span%s>", f.styleAttr(css, chroma.LineHighlight))
			}
			fmt.Fprintf(w, "<span%s%s>%s\n</span>", f.styleAttr(css, chroma.LineNumbersTable), f.lineIDAttribute(line), f.lineTitleWithLinkIfNeeded(css, lineDigits, line))
			if highlight {
				fmt.Fprintf(w, "</span>")
			}
		}
		fmt.Fprint(w, f.preEnd(false))
		fmt.Fprint(w, "</td>\n")
		fmt.Fprintf(w, "<td%s>\n", f.styleAttr(css, chroma.LineTableTD, "width:100%"))
	}
	fmt.Fprintf(w, "%s", f.preStart(true, f.styleAttr(css, chroma.PreWrapper)))
	highlightIndex = 0
	for index, tokens := range lines {
		line := f.BaseLineNumber + index
		highlight, next := f.shouldHighlight(highlightIndex, line)
		if next {
			highlightIndex++
		}
		if !f.PreventSurroundingPre {
			fmt.Fprint(w, `<span`)
			if highlight {
				if f.Classes {
					fmt.Fprintf(w, ` class="%s %s"`, f.class(chroma.Line), f.class(chroma.LineHighlight))
				} else {
					fmt.Fprintf(w, ` style="%s %s"`, css[chroma.Line], css[chroma.LineHighlight])
