package lexers

import (
	"embed"
	"io/fs"
	"sort"

	"hl/chroma"
)

//go:embed embedded
var embedded embed.FS

// Registry is the global lexer registry.
var Registry = chroma.NewLexerRegistry()

var byNameOrder []chroma.Lexer

// XMLFiles returns the names and contents of serialisable lexer definitions.
func XMLFiles() map[string][]byte {
	out := map[string][]byte{}
	paths, _ := fs.Glob(embedded, "embedded/*.xml")
	for _, p := range paths {
		data, _ := fs.ReadFile(embedded, p)
		out[p[len("embedded/"):]] = data
	}
	return out
}

var xmlLexers = map[string]*chroma.RegexLexer{}

func init() {
	paths, err := fs.Glob(embedded, "embedded/*.xml")
	if err != nil {
		panic(err)
	}
	var all []chroma.Lexer
	for _, path := range paths {
		data, _ := fs.ReadFile(embedded, path)
		l, err := chroma.NewXMLLexerFromBytes(data, path)
		if err != nil {
			panic(err)
		}
		xmlLexers[l.Config().Name] = l
		all = append(all, l)
	}
	all = append(all, goLexers()...)
	sort.SliceStable(all, func(i, j int) bool { return all[i].Config().Name < all[j].Config().Name })
	for _, l := range all {
		Registry.Register(l)
	}
	setupAnalysers()
}

// Get a lexer by name, alias or filename.
func Get(name string) chroma.Lexer { return Registry.Get(name) }

// Match a filename.
func Match(filename string) chroma.Lexer { return Registry.Match(filename) }

// Analyse text.
func Analyse(text string) chroma.Lexer { return Registry.Analyse(text) }

// XMLLexer returns an XML-defined lexer by name.
func XMLLexer(name string) *chroma.RegexLexer { return xmlLexers[name] }

func goLexers() []chroma.Lexer { return nil }

func setupAnalysers() {}
