package main

import (
	"fmt"
	"os"
	"path/filepath"
	"strconv"
	"strings"
)

type flagKind int

const (
	kBool flagKind = iota
	kString
	kInt
	kEnum
	kExistingDir
)

type flagDef struct {
	name    string
	short   rune
	kind    flagKind
	enum    []string
	isHook  bool
	set     bool
	bval    bool
	sval    string
	ival    int64
	defStr  string
	defInt  int64
}

type cliOpts struct {
	flags     []*flagDef
	byName    map[string]*flagDef
	byShort   map[rune]*flagDef
	files     []string
	hookOrder []string
}

func newCLI() *cliOpts {
	c := &cliOpts{byName: map[string]*flagDef{}, byShort: map[rune]*flagDef{}}
	add := func(f *flagDef) {
		c.flags = append(c.flags, f)
		c.byName[f.name] = f
		if f.short != 0 {
			c.byShort[f.short] = f
		}
	}
	add(&flagDef{name: "help", short: 'h', kind: kBool, isHook: true})
	add(&flagDef{name: "version", kind: kBool, isHook: true})
	add(&flagDef{name: "profile", kind: kString})
	add(&flagDef{name: "list", kind: kBool})
	add(&flagDef{name: "unbuffered", kind: kBool})
	add(&flagDef{name: "trace", kind: kBool})
	add(&flagDef{name: "check", kind: kBool})
	add(&flagDef{name: "filename", kind: kString})
	add(&flagDef{name: "fail", kind: kBool})
	add(&flagDef{name: "xml", kind: kExistingDir})
	add(&flagDef{name: "lexer", short: 'l', kind: kString, defStr: "autodetect"})
	add(&flagDef{name: "style", short: 's', kind: kString, defStr: "swapoff"})
	add(&flagDef{name: "formatter", short: 'f', kind: kEnum, defStr: "terminal",
		enum: []string{"html", "json", "noop", "svg", "terminal", "terminal16", "terminal16m", "terminal256", "terminal8", "tokens"}})
	add(&flagDef{name: "json", kind: kBool})
	add(&flagDef{name: "html", kind: kBool})
	add(&flagDef{name: "svg", kind: kBool})
	add(&flagDef{name: "html-prefix", kind: kString})
	add(&flagDef{name: "html-styles", kind: kBool})
	add(&flagDef{name: "html-all-styles", kind: kBool})
	add(&flagDef{name: "html-only", kind: kBool})
	add(&flagDef{name: "html-inline-styles", kind: kBool})
	add(&flagDef{name: "html-tab-width", kind: kInt, defInt: 8})
	add(&flagDef{name: "html-lines", kind: kBool})
	add(&flagDef{name: "html-lines-table", kind: kBool})
	add(&flagDef{name: "html-lines-style", kind: kString})
	add(&flagDef{name: "html-highlight", kind: kString})
	add(&flagDef{name: "html-highlight-style", kind: kString})
	add(&flagDef{name: "html-base-line", kind: kInt, defInt: 1})
	add(&flagDef{name: "html-prevent-surrounding-pre", kind: kBool})
	add(&flagDef{name: "html-linkable-lines", kind: kBool})
	for _, f := range c.flags {
		f.sval = f.defStr
		f.ival = f.defInt
	}
	return c
}

func (c *cliOpts) b(name string) bool    { return c.byName[name].bval }
func (c *cliOpts) s(name string) string  { return c.byName[name].sval }
func (c *cliOpts) i(name string) int     { return int(c.byName[name].ival) }
func (c *cliOpts) isSet(name string) bool { return c.byName[name].set }

type parseError struct{ msg string }

func (p *parseError) Error() string { return p.msg }

func levenshtein(a, b string) int {
	ra, rb := []rune(a), []rune(b)
	prev := make([]int, len(rb)+1)
	cur := make([]int, len(rb)+1)
	for j := range prev {
		prev[j] = j
	}
	for i := 1; i <= len(ra); i++ {
		cur[0] = i
		for j := 1; j <= len(rb); j++ {
			cost := 1
			if ra[i-1] == rb[j-1] {
				cost = 0
			}
			cur[j] = minInt(minInt(prev[j]+1, cur[j-1]+1), prev[j-1]+cost)
		}
		prev, cur = cur, prev
	}
	return prev[len(rb)]
}

func minInt(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func (c *cliOpts) unknownFlag(name string) error {
	var candidates []string
	for _, f := range c.flags {
		long := "--" + f.name
		if levenshtein(name, long) <= 2 || strings.HasPrefix(long, name) {
			candidates = append(candidates, long)
		}
		if f.short != 0 {
			short := "-" + string(f.short)
			if levenshtein(name, short) <= 2 || strings.HasPrefix(short, name) {
				candidates = append(candidates, short)
			}
		}
	}
	msg := "unknown flag " + name
	if len(candidates) == 1 {
		msg += fmt.Sprintf(", did you mean %q?", candidates[0])
	} else if len(candidates) > 1 {
		q := make([]string, len(candidates))
		for i, s := range candidates {
			q[i] = strconv.Quote(s)
		}
		msg += ", did you mean one of " + strings.Join(q, ", ") + "?"
	}
	return &parseError{msg}
}

func describeToken(s string) string {
	if strings.HasPrefix(s, "--") {
		return "long flag"
	}
	if strings.HasPrefix(s, "-") && s != "-" {
		return "short flag"
	}
	return "arg"
}

func (c *cliOpts) assign(f *flagDef, value string, hasValue bool, next func() (string, bool)) error {
	switch f.kind {
	case kBool:
		if !hasValue {
			f.bval = true
			f.set = true
			if f.isHook {
				c.hookOrder = append(c.hookOrder, f.name)
			}
			return nil
		}
		switch strings.ToLower(value) {
		case "true", "1", "yes":
			f.bval = true
		case "false", "0", "no":
			f.bval = false
		default:
			return &parseError{fmt.Sprintf("--%s: bool value must be true, 1, yes, false, 0 or no but got %q", f.name, value)}
		}
		f.set = true
		if f.isHook {
			c.hookOrder = append(c.hookOrder, f.name)
		}
		return nil
	}
	if !hasValue {
		v, ok := next()
		typ := "string"
		switch f.kind {
		case kInt:
			typ = "int"
		case kExistingDir:
			typ = "file"
		}
		if !ok {
			return &parseError{fmt.Sprintf("--%s: expected %s value but got \"EOL\" (<EOL>)", f.name, typ)}
		}
		if strings.HasPrefix(v, "-") && v != "-" && f.kind != kInt {
			return &parseError{fmt.Sprintf("--%s: expected %s value but got %q (%s); perhaps try --%s=%q?", f.name, typ, v, describeToken(v), f.name, v)}
		}
		if strings.HasPrefix(v, "-") && v != "-" && f.kind == kInt {
			if _, err := strconv.ParseInt(v, 10, 64); err != nil {
				return &parseError{fmt.Sprintf("--%s: expected %s value but got %q (%s); perhaps try --%s=%q?", f.name, typ, v, describeToken(v), f.name, v)}
			}
		}
		value = v
	}
	f.set = true
	switch f.kind {
	case kString, kEnum:
		f.sval = value
	case kInt:
		n, err := strconv.ParseInt(value, 10, 64)
		if err != nil {
			return &parseError{fmt.Sprintf("--%s: expected a valid 64 bit int but got %q", f.name, value)}
		}
		f.ival = n
	case kExistingDir:
		abs, _ := filepath.Abs(value)
		st, err := os.Stat(abs)
		if err != nil {
			return &parseError{fmt.Sprintf("--%s: %s", f.name, err)}
		}
		if !st.IsDir() {
			return &parseError{fmt.Sprintf("--%s: %q exists but is not a directory", f.name, abs)}
		}
		f.sval = abs
		c.hookOrder = append(c.hookOrder, f.name)
	}
	return nil
}

func (c *cliOpts) addFile(path string) error {
	if path == "-" {
		c.files = append(c.files, path)
		return nil
	}
