output.arguments:
{"command":"cd /workspace && cat > main.go <<'EOF'
package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
	"time"

	"hl/chroma"
	"hl/formatters"
	"hl/lexers"
	"hl/styles"
)

var progName = filepath.Base(os.Args[0])

type exitCode int

func fatalf(code int, format string, args ...interface{}) {
	fmt.Fprintf(os.Stderr, "%s: error: %s\n", progName, fmt.Sprintf(format, args...))
	panic(exitCode(code))
}

func main() {
	code := run()
	os.Exit(code)
}

func run() (code int) {
	var out *bufio.Writer
	defer func() {
		if r := recover(); r != nil {
			if out != nil {
				out.Flush()
			}
			if e, ok := r.(exitCode); ok {
				code = int(e)
				return
			}
			fmt.Fprintf(os.Stderr, "%s: error: %v\n", progName, r)
			code = 1
		}
	}()
	cli := newCLI()
	if err := cli.parse(os.Args[1:]); err != nil {
		fatalf(80, "%s", err)
	}
	if cli.isSet("xml") {
		dumpXML(cli.s("xml"))
	}
	for _, h := range cli.hookOrder {
		switch h {
		case "help":
			fmt.Printf(helpText, progName)
			return 0
		case "version":
			fmt.Println("?-?-?")
			return 0
		}
	}
	if cli.isSet("xml") {
		return 0
	}
	if err := cli.validate(); err != nil {
		fatalf(80, "%s", err)
	}
	if p := cli.s("profile"); p != "" {
		f, err := os.Create(p)
		if err != nil {
			fatalf(1, "%s", err)
		}
		defer f.Close()
	}
	if cli.b("list") {
		listAll()
		return 0
	}
	out = bufio.NewWriterSize(os.Stdout, 16384)
	defer out.Flush()
	var w io.Writer = out
	if cli.b("unbuffered") {
		w = os.Stdout
	}

	style := resolveStyle(cli.s("style"))
	if hs := cli.s("html-highlight-style"); hs != "" {
		e, err := chroma.ParseStyleEntry(hs)
		if err != nil {
			fatalf(1, "invalid entry for LineHighlight: %s", err)
		}
		style = style.Clone()
		style.SetEntry(chroma.LineHighlight, e)
	}
	if ls := cli.s("html-lines-style"); ls != "" {
		e, err := chroma.ParseStyleEntry(ls)
		if err != nil {
			fatalf(1, "invalid entry for LineNumbers: %s", err)
		}
		style = style.Clone()
		style.SetEntry(chroma.LineNumbers, e)
	}

	formatterName := cli.s("formatter")
	if cli.b("json") {
		formatterName = "json"
	} else if cli.b("html") {
		formatterName = "html"
	} else if cli.b("svg") {
		formatterName = "svg"
	}
	htmlFormatter := formatters.NewHTML()
	htmlFormatter.Standalone = true
	htmlFormatter.Classes = true
	if formatterName == "html" {
		configureHTML(cli, htmlFormatter)
	}
	if cli.b("html-styles") {
		if err := htmlFormatter.WriteCSS(w, style); err != nil {
			fatalf(1, "%s", err)
		}
		return 0
	}
	var formatter formatters.Formatter
	switch formatterName {
	case "html":
		formatter = htmlFormatter
	case "json":
		formatter = formatters.JSON
	case "noop":
		formatter = formatters.NoOp
	case "svg":
		formatter = formatters.SVG
	case "terminal", "terminal8":
		formatter = formatters.IndexedTTY(8)
	case "terminal16":
		formatter = formatters.IndexedTTY(16)
	case "terminal256":
		formatter = formatters.IndexedTTY(256)
	case "terminal16m":
		formatter = formatters.TrueColourTTY()
	case "tokens":
		formatter = formatters.Tokens
	}

	if len(cli.files) == 0 {
		contents, err := io.ReadAll(os.Stdin)
		if err != nil {
			fatalf(1, "%s", err)
		}
		lexer := selectLexer(cli, cli.s("filename"), string(contents))
		it := lex(cli, lexer, string(contents))
		if err := formatter.Format(w, style, it); err != nil {
			fatalf(1, "%s", err)
		}
		return 0
	}
	for _, filename := range cli.files {
		data, err := os.ReadFile(filename)
		if err != nil {
			fatalf(1, "%s", err)
		}
		lexer := selectLexer(cli, filename, string(data))
		it := lex(cli, lexer, string(data))
		if cli.b("check") {
			check(w, filename, it)
		} else {
			if err := formatter.Format(w, style, it); err != nil {
				fatalf(1, "%s", err)
			}
		}
	}
	return 0
}

func configureHTML(cli *cliOpts, f *formatters.HTMLFormatter) {
	f.Standalone = !cli.b("html-only")
	f.Classes = !cli.b("html-inline-styles")
	f.AllClasses = cli.b("html-all-styles")
	f.Prefix = cli.s("html-prefix")
	f.TabWidth = cli.i("html-tab-width")
	f.LineNumbers = cli.b("html-lines")
	f.LineNumbersInTable = cli.b("html-lines-table")
	f.PreventSurroundingPre = cli.b("html-prevent-surrounding-pre")
	f.LinkableLineNumbers = cli.b("html-linkable-lines")
	f.BaseLineNumber = cli.i("html-base-line")
	if hl := cli.s("html-highlight"); hl != "" {
		ranges := [][2]int{}
		for _, span := range strings.Split(hl, ",") {
			parts := strings.Split(span, ":")
			if len(parts) > 2 {
				fatalf(1, "range should be N[:M], not %q", span)
			}
			start, err := strconv.ParseInt(parts[0], 10, 64)
			if err != nil {
				fatalf(1, "%s", err)
			}
			end := start
			if len(parts) == 2 {
				end, err = strconv.ParseInt(parts[1], 10, 64)
				if err != nil {
					fatalf(1, "%s", err)
				}
			}
			ranges = append(ranges, [2]int{int(start), int(end)})
