package styles

import (
	"embed"
	"io/fs"
	"sort"
	"strings"

	"hl/chroma"
)

//go:embed embedded
var embedded embed.FS

var registry = map[string]*chroma.Style{}

func init() {
	paths, _ := fs.Glob(embedded, "embedded/*.xml")
	for _, p := range paths {
		data, _ := fs.ReadFile(embedded, p)
		s, err := chroma.NewXMLStyle(data)
		if err != nil {
			panic(p + ": " + err.Error())
		}
		registry[strings.ToLower(s.Name)] = s
	}
}

// Get a style by name (case-insensitive). Returns nil if not found.
func Get(name string) *chroma.Style {
	return registry[strings.ToLower(name)]
}

// Names of all styles (including the unloadable default).
func Names() []string {
	out := []string{"swapoff"}
	for _, s := range registry {
		out = append(out, s.Name)
	}
	sort.Strings(out)
	return out
}
