package lexers

import (
	"strings"

	. "hl/chroma"
)

func httpLexer() Lexer {
	return &httpBodyContentTyper{MustNewLexer(&Config{
		Name:         "HTTP",
		Aliases:      []string{"http"},
		NotMultiline: true,
		DotAll:       true,
	}, httpRules)}
}

func httpRules() Rules {
	return Rules{
		"root": {
			{`(GET|POST|PUT|DELETE|HEAD|OPTIONS|TRACE|PATCH|CONNECT)( +)([^ ]+)( +)(HTTP)(/)([123](?:\.[01])?)(\r?\n|\Z)`, ByGroups(NameFunction, Text, NameNamespace, Text, KeywordReserved, Operator, LiteralNumber, Text), Push("headers")},
			{`(HTTP)(/)([123](?:\.[01])?)( +)(\d{3})( *)([^\r\n]*)(\r?\n|\Z)`, ByGroups(KeywordReserved, Operator, LiteralNumber, Text, LiteralNumber, Text, NameException, Text), Push("headers")},
		},
		"headers": {
			{`([^\s:]+)( *)(:)( *)([^\r\n]+)(\r?\n|\Z)`, ByGroups(Name, Text, Operator, Text, Literal, Text), nil},
			{`([\t ]+)([^\r\n]+)(\r?\n|\Z)`, ByGroups(Text, Literal, Text), nil},
			{`\r?\n`, Text, Push("content")},
		},
		"content": {
			{`.+`, Generic, nil},
		},
	}
}

type httpBodyContentTyper struct{ Lexer }

func (d *httpBodyContentTyper) Tokenise(options *TokeniseOptions, text string) (Iterator, error) {
	var contentType string
	var isContentType bool
	var subIterator Iterator
	it, err := d.Lexer.Tokenise(options, text)
	if err != nil {
		return nil, err
	}
	reg := Registry
	return func() Token {
		for {
			if subIterator != nil {
				t := subIterator()
				if t != EOF {
					return t
				}
				subIterator = nil
			}
			token := it()
			if token == EOF {
				return EOF
			}
			switch {
			case token.Type == Name && strings.ToLower(token.Value) == "content-type":
				isContentType = true
			case token.Type == Literal && isContentType:
				isContentType = false
				contentType = strings.TrimSpace(token.Value)
				pos := strings.Index(contentType, ";")
				if pos > 0 {
					contentType = strings.TrimSpace(contentType[:pos])
				}
			case token.Type == Generic && contentType != "":
				lexer := reg.MatchMimeType(contentType)
				if lexer == nil && strings.Contains(contentType, "+") {
					slashPos := strings.Index(contentType, "/")
					plusPos := strings.LastIndex(contentType, "+")
					ct := contentType[:slashPos+1] + contentType[plusPos+1:]
					lexer = reg.MatchMimeType(ct)
				}
				if lexer == nil {
					token.Type = Text
				} else {
					sub, err := lexer.Tokenise(nil, token.Value)
					if err != nil {
						panic(err)
					}
					subIterator = sub
					continue
				}
			}
			return token
		}
	}, nil
