import json, re, subprocess, itertools, sys
found = json.load(open('/tmp/cl/ebig.json'))
d = json.load(open('/tmp/cl/eclassified.json'))
for k in ('NameFunction','NameBuiltin','NameException','KeywordPseudo'):
    for w in d.get(k, []):
        if not w.startswith(':'): found[w] = k
for it in range(4):
    parts = set()
    for w in found:
        for p in w.split('-'):
            if p: parts.add(p)
    parts = sorted(parts)
    # frequent first parts and last parts
    firsts = sorted(set(w.split('-')[0] for w in found))
    lasts = sorted(set(w.split('-')[-1] for w in found))
    mids = parts
    cands = set()
    for a in parts:
        for b in parts:
            cands.add(a+'-'+b)
    for a in firsts:
        for b in mids:
            for c in lasts:
                cands.add(a+'-'+b+'-'+c)
    cands = [c for c in cands if c not in found]
    print('iter', it, 'parts', len(parts), 'firsts', len(firsts), 'lasts', len(lasts), 'cands', len(cands), flush=True)
