cd /workspace/lexers && cat > haxe.go <<'EOF'
package lexers

import . "hl/chroma"

const (
	hxKeyword        = `(?:function|class|static|var|if|else|while|do|for|break|return|continue|extends|implements|import|switch|case|default|public|private|try|untyped|catch|new|this|throw|extern|enum|in|interface|cast|override|dynamic|typedef|package|inline|using|null|true|false|abstract)\b`
	hxTypeid         = `_*[A-Z]\w*`
	hxIdent          = `(?:_*[a-z]\w*|_+[0-9]\w*|` + hxTypeid + `|_+|\$\w+)`
	hxBinop          = `(?:%=|&=|\|=|\^=|\+=|\-=|\*=|/=|<<=|>\s*>\s*=|>\s*>\s*>\s*=|==|!=|<=|>\s*=|&&|\|\||<<|>>>|>\s*>|\.\.\.|<|>|%|&|\||\^|\+|\*|/|\-|=>|=)`
	hxIdentNoKeyword = `(?!` + hxKeyword + `)` + hxIdent
)

func haxeLexer() Lexer {
	return MustNewLexer(&Config{
		Name:      "Haxe",
		Aliases:   []string{"hx", "haxe", "hxsl"},
		Filenames: []string{"*.hx", "*.hxsl"},
		MimeTypes: []string{"text/haxe", "text/x-haxe", "text/x-hx"},
		DotAll:    true,
	}, haxeRules)
}

func haxePreProcMutator(state *LexerState) error {
	stack, ok := state.Get("haxe-pre-proc").([][]string)
	if !ok {
		stack = [][]string{}
	}
	proc := state.Groups[2]
	switch proc {
	case "if":
		stack = append(stack, state.Stack)
	case "else", "elseif":
		if len(stack) > 0 {
			state.Stack = stack[len(stack)-1]
		}
	case "end":
		if len(stack) > 0 {
			stack = stack[:len(stack)-1]
		}
	}
	if proc == "if" || proc == "elseif" {
		state.Stack = append(state.Stack, "preproc-expr")
	}
	if proc == "error" {
		state.Stack = append(state.Stack, "preproc-error")
	}
	state.Set("haxe-pre-proc", stack)
	return nil
}

func hxFloatInt(mut func() Mutator) []Rule {
	m := func() Mutator {
		if mut == nil {
			return nil
		}
		return mut()
	}
	return []Rule{
		{`\.[0-9]+`, LiteralNumberFloat, m()},
		{`[0-9]+[eE][+\-]?[0-9]+`, LiteralNumberFloat, m()},
		{`[0-9]+\.[0-9]*[eE][+\-]?[0-9]+`, LiteralNumberFloat, m()},
		{`[0-9]+\.[0-9]+`, LiteralNumberFloat, m()},
		{`[0-9]+\.(?!` + hxIdent + `|\.\.)`, LiteralNumberFloat, m()},
		{`0x[0-9a-fA-F]+`, LiteralNumberHex, m()},
		{`[0-9]+`, LiteralNumberInteger, m()},
	}
}

func cat(rs ...[]Rule) []Rule {
	var out []Rule
	for _, r := range rs {
		out = append(out, r...)
	}
	return out
}

func haxeRules() Rules {
	popChain := func() Mutator { return Push("#pop", "preproc-expr-chain") }
	popExprChain := func() Mutator { return Push("#pop", "expr-chain") }
	popOnly := func() Mutator { return Pop(1) }
	return Rules{
		"root": {
			Include("spaces"),
			Include("meta"),
			{`(?:package)\b`, KeywordNamespace, Push("semicolon", "package")},
			{`(?:import)\b`, KeywordNamespace, Push("semicolon", "import")},
			{`(?:using)\b`, KeywordNamespace, Push("semicolon", "using")},
			{`(?:extern|private)\b`, KeywordDeclaration, nil},
			{`(?:abstract)\b`, KeywordDeclaration, Push("abstract")},
			{`(?:class|interface)\b`, KeywordDeclaration, Push("class")},
			{`(?:enum)\b`, KeywordDeclaration, Push("enum")},
			{`(?:typedef)\b`, KeywordDeclaration, Push("typedef")},
			{`(?=.)`, Text, Push("expr-statement")},
		},
		"spaces": {
			{`\s+`, Text, nil},
			{`//[^\n\r]*`, CommentSingle, nil},
			{`/\*.*?\*/`, CommentMultiline, nil},
			{`(#)(if|elseif|else|end|error)\b`, CommentPreproc, MutatorFunc(haxePreProcMutator)},
		},
		"string-single-interpol": {
			{`\$\{`, LiteralStringInterpol, Push("string-interpol-close", "expr")},
			{`\$\$`, LiteralStringEscape, nil},
